INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s173', 'ᱟᱞᱚᱢ ᱠᱤᱛᱟᱹᱣᱜᱼᱟ, ᱫᱟᱭᱟ ᱫᱚᱦᱚᱭ ᱢᱮ᱾', 'Alom kitaug-a, daya dohoy me.', NULL, 'Emotions', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s173/view?project=699495910038e39622c5', 0, '{"id":"s173","sentenceOlChiki":"ᱟᱞᱚᱢ ᱠᱤᱛᱟᱹᱣᱜᱼᱟ, ᱫᱟᱭᱟ ᱫᱚᱦᱚᱭ ᱢᱮ᱾","sentenceLatin":"Alom kitaug-a, daya dohoy me.","meaning":"Do not be angry, hold compassion.","usage":null,"category":"Emotions","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s173/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":173,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
