INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s175', 'ᱥᱟᱹᱨᱤ ᱠᱟᱛᱷᱟ ᱨᱚᱲ ᱞᱮᱠᱷᱟᱱ ᱢᱚᱱᱮ ᱥᱟᱯᱷᱟ ᱛᱟᱦᱮᱸᱱᱟ᱾', 'Sari katha ror lekhan mone sapha tahena.', NULL, 'Emotions', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s175/view?project=699495910038e39622c5', 0, '{"id":"s175","sentenceOlChiki":"ᱥᱟᱹᱨᱤ ᱠᱟᱛᱷᱟ ᱨᱚᱲ ᱞᱮᱠᱷᱟᱱ ᱢᱚᱱᱮ ᱥᱟᱯᱷᱟ ᱛᱟᱦᱮᱸᱱᱟ᱾","sentenceLatin":"Sari katha ror lekhan mone sapha tahena.","meaning":"Speaking truth keeps the mind clear.","usage":null,"category":"Emotions","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s175/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":175,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s176', 'ᱟᱢ ᱫᱚ ᱪᱮᱫᱟᱜ ᱮᱢ ᱵᱚᱛᱚᱨᱚᱜ ᱠᱟᱱᱟ?', 'Am do cedag em botorog kana?', NULL, 'Emotions', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s176/view?project=699495910038e39622c5', 0, '{"id":"s176","sentenceOlChiki":"ᱟᱢ ᱫᱚ ᱪᱮᱫᱟᱜ ᱮᱢ ᱵᱚᱛᱚᱨᱚᱜ ᱠᱟᱱᱟ?","sentenceLatin":"Am do cedag em botorog kana?","meaning":"Why are you feeling afraid?","usage":null,"category":"Emotions","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s176/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":176,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s177', 'ᱥᱟᱱᱛᱟᱲᱤ ᱯᱟᱹᱨᱥᱤ ᱛᱮ ᱨᱚᱲ ᱫᱚ ᱟᱹᱰᱤ ᱜᱚᱨᱚᱵᱽ ᱨᱮᱭᱟᱜ ᱠᱟᱛᱷᱟ ᱠᱟᱱᱟ᱾', 'Santali parsi te ror do adi gorob reyag katha kana.', NULL, 'Emotions', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s177/view?project=699495910038e39622c5', 0, '{"id":"s177","sentenceOlChiki":"ᱥᱟᱱᱛᱟᱲᱤ ᱯᱟᱹᱨᱥᱤ ᱛᱮ ᱨᱚᱲ ᱫᱚ ᱟᱹᱰᱤ ᱜᱚᱨᱚᱵᱽ ᱨᱮᱭᱟᱜ ᱠᱟᱛᱷᱟ ᱠᱟᱱᱟ᱾","sentenceLatin":"Santali parsi te ror do adi gorob reyag katha kana.","meaning":"Speaking in the Santali language is a matter of great pride.","usage":null,"category":"Emotions","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s177/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":177,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s178', 'ᱤᱧ ᱫᱚ ᱟᱢ ᱨᱮ ᱯᱟᱹᱛᱭᱟᱹᱣ ᱢᱮᱱᱟᱜᱼᱛᱤᱧᱟ᱾', 'Iny do am re patyaw menag-tiny-a.', NULL, 'Emotions', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s178/view?project=699495910038e39622c5', 0, '{"id":"s178","sentenceOlChiki":"ᱤᱧ ᱫᱚ ᱟᱢ ᱨᱮ ᱯᱟᱹᱛᱭᱟᱹᱣ ᱢᱮᱱᱟᱜᱼᱛᱤᱧᱟ᱾","sentenceLatin":"Iny do am re patyaw menag-tiny-a.","meaning":"I have trust and faith in you.","usage":null,"category":"Emotions","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s178/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":178,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
