INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s180', 'ᱨᱟᱹᱥᱠᱟᱹ ᱛᱮ ᱡᱤᱭᱚᱱ ᱠᱷᱟᱸᱰᱟᱣ ᱢᱮ᱾', 'Raska te jiyon khandaw me.', NULL, 'Emotions', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s180/view?project=699495910038e39622c5', 0, '{"id":"s180","sentenceOlChiki":"ᱨᱟᱹᱥᱠᱟᱹ ᱛᱮ ᱡᱤᱭᱚᱱ ᱠᱷᱟᱸᱰᱟᱣ ᱢᱮ᱾","sentenceLatin":"Raska te jiyon khandaw me.","meaning":"Live your life with joy.","usage":null,"category":"Emotions","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s180/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":180,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s181', 'ᱡᱚᱦᱟᱨ ᱜᱚᱢᱠᱮ, ᱫᱮᱞᱟ ᱵᱷᱤᱛᱨᱤ ᱛᱮ ᱦᱤᱡᱩᱜ ᱵᱤᱱ᱾', 'Johar gomke, dela bhitri te hijug bin.', NULL, 'Courtesies', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s181/view?project=699495910038e39622c5', 0, '{"id":"s181","sentenceOlChiki":"ᱡᱚᱦᱟᱨ ᱜᱚᱢᱠᱮ, ᱫᱮᱞᱟ ᱵᱷᱤᱛᱨᱤ ᱛᱮ ᱦᱤᱡᱩᱜ ᱵᱤᱱ᱾","sentenceLatin":"Johar gomke, dela bhitri te hijug bin.","meaning":"Greetings sir, please come inside.","usage":null,"category":"Courtesies","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s181/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":181,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
