INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s183', 'ᱟᱹᱰᱤ ᱟᱹᱰᱤ ᱥᱟᱨᱦᱟᱣ ᱟᱢᱟᱜ ᱫᱟᱭᱟ ᱞᱟᱹᱜᱤᱫ᱾', 'Adi adi sarhaw amag daya lagid.', NULL, 'Courtesies', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s183/view?project=699495910038e39622c5', 0, '{"id":"s183","sentenceOlChiki":"ᱟᱹᱰᱤ ᱟᱹᱰᱤ ᱥᱟᱨᱦᱟᱣ ᱟᱢᱟᱜ ᱫᱟᱭᱟ ᱞᱟᱹᱜᱤᱫ᱾","sentenceLatin":"Adi adi sarhaw amag daya lagid.","meaning":"Thank you very much for your kindness.","usage":null,"category":"Courtesies","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s183/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":183,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
