INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s192', 'ᱛᱚᱵᱮ ᱤᱧ ᱪᱟᱞᱟᱣ ᱞᱮᱱᱜᱮ, ᱡᱚᱦᱟᱨ᱾', 'Tobe iny chalaw lenge, Johar.', NULL, 'Courtesies', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s192/view?project=699495910038e39622c5', 0, '{"id":"s192","sentenceOlChiki":"ᱛᱚᱵᱮ ᱤᱧ ᱪᱟᱞᱟᱣ ᱞᱮᱱᱜᱮ, ᱡᱚᱦᱟᱨ᱾","sentenceLatin":"Tobe iny chalaw lenge, Johar.","meaning":"Then I shall take my leave, farewell.","usage":null,"category":"Courtesies","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s192/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":192,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
