INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s208', 'ᱫᱟᱜ ᱟᱹᱰᱤ ᱡᱩᱨ ᱛᱮᱛᱟᱝ ᱟᱠᱟᱫᱤᱧᱟ᱾', 'Dag adi jur tetang akadiny-a.', NULL, 'Health', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s208/view?project=699495910038e39622c5', 0, '{"id":"s208","sentenceOlChiki":"ᱫᱟᱜ ᱟᱹᱰᱤ ᱡᱩᱨ ᱛᱮᱛᱟᱝ ᱟᱠᱟᱫᱤᱧᱟ᱾","sentenceLatin":"Dag adi jur tetang akadiny-a.","meaning":"I am feeling very thirsty for water.","usage":null,"category":"Health","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s208/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":208,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s209', 'ᱨᱮᱸᱜᱮᱡ ᱟᱠᱟᱫᱤᱧᱟ, ᱫᱟᱠᱟ ᱤᱧ ᱡᱚᱢᱟ᱾', 'Rengej akadiny-a, daka iny joma.', NULL, 'Health', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s209/view?project=699495910038e39622c5', 0, '{"id":"s209","sentenceOlChiki":"ᱨᱮᱸᱜᱮᱡ ᱟᱠᱟᱫᱤᱧᱟ, ᱫᱟᱠᱟ ᱤᱧ ᱡᱚᱢᱟ᱾","sentenceLatin":"Rengej akadiny-a, daka iny joma.","meaning":"I am feeling hungry, I will eat food.","usage":null,"category":"Health","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s209/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":209,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s210', 'ᱦᱚᱲᱢᱚ ᱨᱮ ᱨᱩᱣᱟᱹ ᱵᱟᱹᱱᱩᱜᱼᱟ, ᱱᱟᱯᱟᱭ ᱜᱮ ᱢᱮᱱᱟᱹᱧᱟ᱾', 'Hormo re ruwa banug-a, napay ge menanya.', NULL, 'Health', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s210/view?project=699495910038e39622c5', 0, '{"id":"s210","sentenceOlChiki":"ᱦᱚᱲᱢᱚ ᱨᱮ ᱨᱩᱣᱟᱹ ᱵᱟᱹᱱᱩᱜᱼᱟ, ᱱᱟᱯᱟᱭ ᱜᱮ ᱢᱮᱱᱟᱹᱧᱟ᱾","sentenceLatin":"Hormo re ruwa banug-a, napay ge menanya.","meaning":"There is no fever in the body, I am fine.","usage":null,"category":"Health","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s210/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":210,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s211', 'ᱟᱞᱮ ᱟᱹᱛᱩ ᱨᱮ ᱢᱟᱺᱡᱷᱤ ᱦᱟᱲᱟᱢ ᱫᱚ ᱵᱤᱪᱟᱹᱨ ᱮᱫᱟᱭ᱾', 'Ale atu re Manjhi haram do bicar eday.', NULL, 'Culture', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s211/view?project=699495910038e39622c5', 0, '{"id":"s211","sentenceOlChiki":"ᱟᱞᱮ ᱟᱹᱛᱩ ᱨᱮ ᱢᱟᱺᱡᱷᱤ ᱦᱟᱲᱟᱢ ᱫᱚ ᱵᱤᱪᱟᱹᱨ ᱮᱫᱟᱭ᱾","sentenceLatin":"Ale atu re Manjhi haram do bicar eday.","meaning":"In our village, the village chief (Manjhi Haram) leads the council meeting.","usage":null,"category":"Culture","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s211/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":211,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
