INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s215', 'ᱥᱚᱦᱨᱟᱭ ᱯᱚᱨᱚᱵᱽ ᱫᱚ ᱥᱟᱱᱛᱟᱲ ᱠᱚᱣᱟᱜ ᱢᱟᱨᱟᱝ ᱯᱚᱨᱚᱵᱽ ᱠᱟᱱᱟ᱾', 'Sohrai Porob do Santhal kowag marang porob kana.', NULL, 'Culture', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s215/view?project=699495910038e39622c5', 0, '{"id":"s215","sentenceOlChiki":"ᱥᱚᱦᱨᱟᱭ ᱯᱚᱨᱚᱵᱽ ᱫᱚ ᱥᱟᱱᱛᱟᱲ ᱠᱚᱣᱟᱜ ᱢᱟᱨᱟᱝ ᱯᱚᱨᱚᱵᱽ ᱠᱟᱱᱟ᱾","sentenceLatin":"Sohrai Porob do Santhal kowag marang porob kana.","meaning":"Sohrai festival is the grandest harvest celebration of the Santal people.","usage":null,"category":"Culture","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s215/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":215,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
