INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s239', 'ᱜᱟᱹᱰᱤ ᱛᱤᱸᱜᱩ ᱟᱠᱟᱱᱟ, ᱫᱮᱡᱚᱜ ᱢᱮ᱾', 'Gari tingu akana, dejog me.', NULL, 'Travel', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s239/view?project=699495910038e39622c5', 0, '{"id":"s239","sentenceOlChiki":"ᱜᱟᱹᱰᱤ ᱛᱤᱸᱜᱩ ᱟᱠᱟᱱᱟ, ᱫᱮᱡᱚᱜ ᱢᱮ᱾","sentenceLatin":"Gari tingu akana, dejog me.","meaning":"The vehicle has stopped, please board.","usage":null,"category":"Travel","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s239/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":239,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s240', 'ᱥᱟᱹᱜᱩᱱ ᱦᱚᱨ ᱛᱟᱦᱮᱸᱱ ᱛᱟᱢ ᱢᱟ᱾', 'Sagun hor tahen tam ma.', NULL, 'Travel', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s240/view?project=699495910038e39622c5', 0, '{"id":"s240","sentenceOlChiki":"ᱥᱟᱹᱜᱩᱱ ᱦᱚᱨ ᱛᱟᱦᱮᱸᱱ ᱛᱟᱢ ᱢᱟ᱾","sentenceLatin":"Sagun hor tahen tam ma.","meaning":"May your journey be blessed and safe.","usage":null,"category":"Travel","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s240/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":240,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s241', 'ᱡᱟᱹᱯᱩᱫ ᱫᱤᱱ ᱨᱮ ᱵᱟᱹᱫᱽ ᱠᱚ ᱫᱟᱜ ᱛᱮ ᱯᱮᱨᱮᱡᱚᱜᱼᱟ᱾', 'Japud din re bad ko dag te perejog-a.', NULL, 'Weather', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s241/view?project=699495910038e39622c5', 0, '{"id":"s241","sentenceOlChiki":"ᱡᱟᱹᱯᱩᱫ ᱫᱤᱱ ᱨᱮ ᱵᱟᱹᱫᱽ ᱠᱚ ᱫᱟᱜ ᱛᱮ ᱯᱮᱨᱮᱡᱚᱜᱼᱟ᱾","sentenceLatin":"Japud din re bad ko dag te perejog-a.","meaning":"In the monsoon season, fields get filled with water.","usage":null,"category":"Weather","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s241/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":241,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s242', 'ᱨᱟᱵᱟᱝ ᱫᱤᱱ ᱨᱮ ᱟᱞᱮ ᱫᱚ ᱞᱚᱞᱚ ᱞᱩᱜᱽᱲᱤ ᱞᱮ ᱦᱚᱨᱚᱜᱟ᱾', 'Rabang din re ale do lolo lugri le horoga.', NULL, 'Weather', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s242/view?project=699495910038e39622c5', 0, '{"id":"s242","sentenceOlChiki":"ᱨᱟᱵᱟᱝ ᱫᱤᱱ ᱨᱮ ᱟᱞᱮ ᱫᱚ ᱞᱚᱞᱚ ᱞᱩᱜᱽᱲᱤ ᱞᱮ ᱦᱚᱨᱚᱜᱟ᱾","sentenceLatin":"Rabang din re ale do lolo lugri le horoga.","meaning":"In the winter season, we wear warm clothes.","usage":null,"category":"Weather","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s242/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":242,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s243', 'ᱱᱤᱨᱚᱱ ᱫᱤᱱ ᱨᱮ ᱫᱷᱟᱹᱨᱛᱤ ᱫᱚ ᱪᱚᱨᱚᱠ ᱧᱮᱞᱚᱜᱼᱟ᱾', 'Niron din re dharti do corok nyelog-a.', NULL, 'Weather', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s243/view?project=699495910038e39622c5', 0, '{"id":"s243","sentenceOlChiki":"ᱱᱤᱨᱚᱱ ᱫᱤᱱ ᱨᱮ ᱫᱷᱟᱹᱨᱛᱤ ᱫᱚ ᱪᱚᱨᱚᱠ ᱧᱮᱞᱚᱜᱼᱟ᱾","sentenceLatin":"Niron din re dharti do corok nyelog-a.","meaning":"In spring season, the earth looks vibrant and charming.","usage":null,"category":"Weather","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s243/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":243,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s244', 'ᱥᱤᱛᱩᱝ ᱫᱤᱱ ᱨᱮ ᱫᱟᱜ ᱟᱹᱰᱤ ᱞᱟᱹᱠᱛᱤᱜᱼᱟ᱾', 'Situng din re dag adi laktig-a.', NULL, 'Weather', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s244/view?project=699495910038e39622c5', 0, '{"id":"s244","sentenceOlChiki":"ᱥᱤᱛᱩᱝ ᱫᱤᱱ ᱨᱮ ᱫᱟᱜ ᱟᱹᱰᱤ ᱞᱟᱹᱠᱛᱤᱜᱼᱟ᱾","sentenceLatin":"Situng din re dag adi laktig-a.","meaning":"In the summer season, water is essential.","usage":null,"category":"Weather","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s244/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":244,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s245', 'ᱛᱮᱦᱮᱧ ᱫᱚ ᱨᱤᱢᱤᱞ ᱟᱠᱟᱫᱟᱭ, ᱫᱟᱜ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾', 'Teheny do rimil akaday, dag dareyag-a.', NULL, 'Weather', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s245/view?project=699495910038e39622c5', 0, '{"id":"s245","sentenceOlChiki":"ᱛᱮᱦᱮᱧ ᱫᱚ ᱨᱤᱢᱤᱞ ᱟᱠᱟᱫᱟᱭ, ᱫᱟᱜ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾","sentenceLatin":"Teheny do rimil akaday, dag dareyag-a.","meaning":"Today it is cloudy, it might rain.","usage":null,"category":"Weather","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s245/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":245,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s246', 'ᱦᱚᱭ ᱵᱟᱹᱨᱰᱩ ᱦᱤᱡᱩᱜ ᱠᱟᱱᱟ, ᱚᱲᱟᱜ ᱵᱚᱞᱚᱱ ᱯᱮ᱾', 'Hoy bardu hijug kana, orag bolon pe.', NULL, 'Weather', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s246/view?project=699495910038e39622c5', 0, '{"id":"s246","sentenceOlChiki":"ᱦᱚᱭ ᱵᱟᱹᱨᱰᱩ ᱦᱤᱡᱩᱜ ᱠᱟᱱᱟ, ᱚᱲᱟᱜ ᱵᱚᱞᱚᱱ ᱯᱮ᱾","sentenceLatin":"Hoy bardu hijug kana, orag bolon pe.","meaning":"A whirlwind/storm is coming, get inside the house.","usage":null,"category":"Weather","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s246/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":246,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s247', 'ᱥᱮᱛᱟᱜ ᱨᱮ ᱥᱤᱥᱤᱨ ᱫᱟᱜ ᱧᱩᱨᱩᱜ ᱠᱟᱱᱟ᱾', 'Setag re sisir dag nyurug kana.', NULL, 'Weather', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s247/view?project=699495910038e39622c5', 0, '{"id":"s247","sentenceOlChiki":"ᱥᱮᱛᱟᱜ ᱨᱮ ᱥᱤᱥᱤᱨ ᱫᱟᱜ ᱧᱩᱨᱩᱜ ᱠᱟᱱᱟ᱾","sentenceLatin":"Setag re sisir dag nyurug kana.","meaning":"Dew drops are falling in the morning.","usage":null,"category":"Weather","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s247/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":247,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s248', 'ᱥᱤᱸᱜᱤ ᱪᱟᱸᱫᱚ ᱨᱟᱠᱟᱵ ᱛᱮ ᱫᱷᱟᱹᱨᱛᱤ ᱢᱟᱨᱥᱟᱞ ᱮᱱᱟ᱾', 'Singi Cando rakab te dharti marsal ena.', NULL, 'Weather', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s248/view?project=699495910038e39622c5', 0, '{"id":"s248","sentenceOlChiki":"ᱥᱤᱸᱜᱤ ᱪᱟᱸᱫᱚ ᱨᱟᱠᱟᱵ ᱛᱮ ᱫᱷᱟᱹᱨᱛᱤ ᱢᱟᱨᱥᱟᱞ ᱮᱱᱟ᱾","sentenceLatin":"Singi Cando rakab te dharti marsal ena.","meaning":"With the sunrise, the whole earth is illuminated with light.","usage":null,"category":"Weather","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s248/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":248,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
