INSERT OR REPLACE INTO sentences (id, sentence_ol_chiki, sentence_latin, translation, category, audio_url, order_index, raw_json) VALUES ('s250', 'ᱥᱟᱱᱟᱢ ᱢᱟᱹᱱᱢᱤ ᱥᱟᱹᱨᱤ ᱫᱷᱚᱨᱚᱢ ᱛᱮ ᱥᱩᱞᱩᱠ ᱨᱮ ᱠᱚ ᱛᱟᱦᱮᱸᱱ ᱢᱟ᱾', 'Sanam manmi Sari Dhorom te suluk re ko tahen ma.', NULL, 'Weather', 'https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s250/view?project=699495910038e39622c5', 0, '{"id":"s250","sentenceOlChiki":"ᱥᱟᱱᱟᱢ ᱢᱟᱹᱱᱢᱤ ᱥᱟᱹᱨᱤ ᱫᱷᱚᱨᱚᱢ ᱛᱮ ᱥᱩᱞᱩᱠ ᱨᱮ ᱠᱚ ᱛᱟᱦᱮᱸᱱ ᱢᱟ᱾","sentenceLatin":"Sanam manmi Sari Dhorom te suluk re ko tahen ma.","meaning":"May all humanity live in truth and peaceful harmony.","usage":null,"category":"Weather","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/sentence_s250/view?project=699495910038e39622c5","imageUrl":null,"pronunciation":null,"orderIndex":0,"animationUrl":null,"order":250,"isActive":true,"themeColor":null,"hero_media":null,"blocks":null,"tracing":null}');
