INSERT OR REPLACE INTO lessons (id, category_id, title_ol_chiki, title_latin, lesson_type, order_index, raw_json) VALUES ('lesson_alphabet_0', 'cat_alphabets_1778594017948', 'ᱨᱟᱦᱟ ᱟᱲᱟᱝ (ᱢᱩᱞ ᱖ ᱜᱚᱴᱟᱝ)', 'The 6 Vowels (Raha Arang)', NULL, 0, '{"id":"lesson_alphabet_0","categoryId":"cat_alphabets_1778594017948","titleOlChiki":"ᱨᱟᱦᱟ ᱟᱲᱟᱝ (ᱢᱩᱞ ᱖ ᱜᱚᱴᱟᱝ)","titleLatin":"The 6 Vowels (Raha Arang)","level":"beginner","orderIndex":0,"isActive":true,"estimatedMinutes":5,"description":"","thumbnailUrl":null,"isPremium":false,"audioUrl":null,"blocks":[{"id":"blk_0","order":0,"type":"text","markdown":"Ol Chiki has 6 basic vowels called Raha Arang (ᱨᱟᱦᱟ ᱟᱲᱟᱝ).","textOlChiki":"ᱨᱟᱦᱟ ᱟᱲᱟᱝ ᱫᱚ ᱛᱩᱨᱩᱭ ᱜᱚᱴᱟᱝ ᱢᱮᱱᱟᱜᱼᱟ᱾","textLatin":"Ol Chiki has 6 basic vowels called Raha Arang (ᱨᱟᱦᱟ ᱟᱲᱟᱝ).","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_alphabet_0_intro/view?project=699495910038e39622c5","meta":{"textBengali":"রাহা আড়াং দ তুরুয় গটাং মেনাঃ-আ।","textHindi":"राहा आड़ांग द तुरुय गोटांग मेनाग-आ।","textOdia":"ରାହା ଆଡ଼ାଙ୍ଗ ଦ ତୁରୁୟ ଗଟାଙ୍ଗ ମେନାଗ-ଆ।","pronunciation":"Raha arang do turuy gotang menag-a.","meaning":"There are 6 basic vowels in Ol Chiki.","meaning_en":"There are 6 basic vowels in Ol Chiki.","meaning_bn":"অল চিকিতে মূল ৬টি স্বরবর্ণ রয়েছে।","meaning_hi":"ओल चिकी में मूल ६ स्वर वर्ण हैं।","meaning_or":"ଅଲ ଚିକିରେ ମୂଳ ୬ଟି ସ୍ୱରବର୍ଣ୍ଣ ରହିଛି।","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_alphabet_0_intro/view?project=699495910038e39622c5"}},{"id":"blk_1","order":1,"type":"text","markdown":"ᱚ (a)– as in ᱚᱞ","textOlChiki":"ᱚ - ᱚᱞ","textLatin":"ᱚ (a)– as in ᱚᱞ","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/6a2250190a7f82535f27/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/6a2250190a7f82535f27/view?project=699495910038e39622c5","textBengali":"অ - অল (লেখা )","textHindi":"अ - अल","textOdia":"ଅ - ଅଲ","pronunciation":"ᱚ (a)– as in ᱚᱞ","meaning":"Vowel ᱚ (a), as in ᱚᱞ (Ol: To write)","meaning_en":"Vowel ᱚ (a), as in ᱚᱞ (Ol: To write)","meaning_bn":"স্বরবর্ণ ᱚ (ল), যেমন ᱚᱞ (অল: লেখা )","meaning_hi":"स्वर ᱚ (ल), जैसे ᱚᱞ (ओल: लिखना)","meaning_or":"ସ୍ୱରବର୍ଣ୍ଣ ᱚ (ଲ), ଯେପରି ᱚᱞ (ଅଲ୍: ଲେଖିବା )"}},{"id":"blk_2","order":2,"type":"text","markdown":"ᱟ (aa) – as in ᱟᱭᱳ","textOlChiki":"ᱟ - ᱟᱭᱳ","textLatin":"ᱟ (aa) – as in ᱟᱭᱳ","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/6a225105a16085db8931/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/6a225105a16085db8931/view?project=699495910038e39622c5","textBengali":"আ - আয়ো","textHindi":"आ - आयो","textOdia":"ଆ - ଆୟୋ","pronunciation":"ᱟ (aa) – as in ᱟᱭᱳ","meaning":"Vowel ᱟ (aa), as in ᱟᱭᱳ (Ayo: Mother)","meaning_en":"Vowel ᱟ (aa), as in ᱟᱭᱳ (Ayo: Mother)","meaning_bn":"স্বরবর্ণ ᱟ (আ), যেমন ᱟᱭᱳ (আয়ো: মা)","meaning_hi":"स्वर ᱟ  जैसे ᱟᱭᱳ (आयो: माँ)","meaning_or":"ସ୍ୱରବର୍ଣ୍ଣ ᱟ,  ଯେପରି ᱟୟୋ (ଆୟୋ: ମାଆ)"}},{"id":"blk_3","order":3,"type":"text","markdown":"ᱤ (I) – as in ᱤᱧ","textOlChiki":"ᱤ - ᱤᱧ","textLatin":"ᱤ (I) – as in ᱤᱧ","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/6a2251b5cfc383d059c4/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/6a2251b5cfc383d059c4/view?project=699495910038e39622c5","textBengali":"ই - ইঞ","textHindi":"इ - इञ","textOdia":"ଇ - ଇଞ","pronunciation":"ᱤ (I) – as in ᱤᱧ","meaning":"Vowel ᱤ (i), as in ᱤᱧ (Iny: I / Me)","meaning_en":"Vowel ᱤ (i), as in ᱤᱧ (Iny: I / Me)","meaning_bn":"স্বরবর্ণ ᱤ (ই), যেমন ᱤᱧ (ইঞ: আমি)","meaning_hi":"स्वर ᱤ (लि), जैसे ᱤᱧ (इञ: मैं)","meaning_or":"ସ୍ୱରବର୍ଣ୍ଣ ᱤ (ଲି), ଯେପରି ᱤଞ (ମୁଁ)"}},{"id":"blk_4","order":4,"type":"text","markdown":"ᱩ (u) – as in ᱩᱞ","textOlChiki":"ᱩ - ᱩᱞ","textLatin":"ᱩ (u) – as in ᱩᱞ","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/6a22525a21ef8b1b0c78/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/6a22525a21ef8b1b0c78/view?project=699495910038e39622c5","textBengali":"উ - উল","textHindi":"उ - उल","textOdia":"ଉ - ଉଲ","pronunciation":"ᱩ (u) – as in ᱩᱞ","meaning":"Vowel ᱩ (u), as in ᱩᱞ (Ul: Mango)","meaning_en":"Vowel ᱩ (u), as in ᱩᱞ (Ul: Mango)","meaning_bn":"স্বরবর্ণ ᱩ (লউ), যেমন ᱩᱞ (উল: আম)","meaning_hi":"स्वर ᱩ (लु), जैसे ᱩᱞ (उल: आम)","meaning_or":"ସ୍ୱରବର୍ଣ୍ଣ ᱩ (ଲୁ), ଯେପରି ଉଲ୍ (ଆମ୍ବ)"}},{"id":"blk_5","order":5,"type":"text","markdown":"ᱮ (E) – as in ᱮᱱᱮᱡ","textOlChiki":"ᱮ - ᱮᱱᱮᱡ","textLatin":"ᱮ (E) – as in ᱮᱱᱮᱡ","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/6a2252dc708c86888ec6/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/6a2252dc708c86888ec6/view?project=699495910038e39622c5","textBengali":"এ - এনেজ","textHindi":"ए - एनेज","textOdia":"ଏ - ଏନେଜ","pronunciation":"ᱮ (e) – as in ᱮᱱᱮᱡ","meaning":"Vowel ᱮ (E) as in ᱮᱱᱮᱡ (Enej: Dance)","meaning_en":"Vowel ᱮ (E) as in ᱮᱱᱮᱡ (Enej: Dance)","meaning_bn":"স্বরবর্ণ ᱮ (এ), যেমন ᱮᱱᱮᱡ (এনেজ: নাচ)","meaning_hi":"स्वर ᱮ , जैसे ᱮᱱᱮᱡ (एनेज: नाचना / नृत्य)","meaning_or":"ସ୍ୱରବର୍ଣ୍ଣ ᱮ, ଯେପରି ଏନେଜ୍ (ନାଚିବା)"}},{"id":"blk_6","order":6,"type":"text","markdown":"ᱳ (O) – as in ᱳᱲᱟᱜ","textOlChiki":"ᱳ - ᱳᱲᱟᱜ","textLatin":"ᱳ (O) – as in ᱳᱲᱟᱜ","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/6a2259f209c40c851e46/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/6a2259f209c40c851e46/view?project=699495910038e39622c5","textBengali":"ও - ওড়াঃ","textHindi":"ओ - ओड़ाग","textOdia":"ଓ - ଓଡ଼ାଗ","pronunciation":"ᱳ (O) – as in ᱳᱲᱟᱜ","meaning":"Vowel ᱳ (O), as in ᱳᱲᱟᱜ (Orag: House / Home)","meaning_en":"Vowel ᱳ (O), as in ᱳᱲᱟᱜ (Orag: House / Home)","meaning_bn":"স্বরবর্ণ ᱳ (ও), যেমন ᱳᱲᱟᱜ (ওড়াঃ: ঘর / বাড়ি)","meaning_hi":"स्वर ᱳ (O), जैसे ᱳᱲᱟᱜ (ओड़ाग: घर / मकान)","meaning_or":"ସ୍ୱରବର୍ଣ୍ଣ ଓ (O), ଯେପରି ଓଡ଼ାଗ୍ (ଘର)"}}],"order":0,"heroMediaUrl":null,"heroMediaType":null,"heroPosterUrl":null,"hero_media":null,"tracing":null,"isPreview":false}');
INSERT OR REPLACE INTO lessons (id, category_id, title_ol_chiki, title_latin, lesson_type, order_index, raw_json) VALUES ('lesson_sentences_basics', 'cat_sentences_1778594024495', 'ᱢᱩᱞ ᱣᱟᱠᱭ', 'Basic Sentences', NULL, 0, '{"id":"lesson_sentences_basics","categoryId":"cat_sentences_1778594024495","titleOlChiki":"ᱢᱩᱞ ᱣᱟᱠᱭ","titleLatin":"Basic Sentences","level":"beginner","orderIndex":0,"isActive":true,"estimatedMinutes":5,"description":"","thumbnailUrl":null,"isPremium":false,"audioUrl":null,"blocks":[{"id":"","order":0,"type":"text","markdown":"Amaag nyutum ched?","textOlChiki":"ᱟᱢᱟᱜ ᱧᱩᱛᱩᱢ ᱪᱮᱫ?","textLatin":"Amaag nyutum ched?","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_basics_0/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_basics_0/view?project=699495910038e39622c5","textBengali":"আমাঃ ঞুতুম চেদ?","textHindi":"आमाग ञुतुम चेद?","textOdia":"ଆମାଗ ଞୁତୁମ ଚେଦ?","emotion":"Curiosity","storyArc":"Making New Friend","growthValue":"Communication","characterGoal":"Make a new friend","imageDirection":"Olitun walks along a winding path in the beautiful green village, pointing with curiosity toward the horizon. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Eyes wide with wonder, body leaning forward, pointing with an inquisitive finger.","learningMoment":"Olitun demonstrating active observation and a love for finding out new things.","meaning":"What is your name?","meaning_en":"What is your name?","meaning_bn":"তোমার নাম কী?","pronunciation":"Amaag nyutum ched?","meaning_hi":"तुम्हारा नाम क्या है?","meaning_or":"ତୁମର ନାମ କ’ଣ?"}},{"id":"","order":1,"type":"text","markdown":"Injaag nyutum do Santhal.","textOlChiki":"ᱤᱧᱟᱜ ᱧᱩᱛᱩᱢ ᱫᱚ ᱥᱟᱱᱛᱷᱟᱞ।","textLatin":"Injaag nyutum do Santhal.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_basics_1/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_basics_1/view?project=699495910038e39622c5","textBengali":"ইঞাঃ ঞুতুম দ সানথাল।","textHindi":"इञाग ञुतुम द सानथाल।","textOdia":"ଇଞାଗ ଞୁତୁମ ଦ ସାନଥାଲ।","emotion":"Friendship","storyArc":"Exploring Village","growthValue":"Confidence","characterGoal":"Learn something new","imageDirection":"a young Santhal child classmate sits peacefully under a large shady tree, looking out over the village with a happy smile. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Warm direct eye contact, relaxed shoulders, open arms in a welcoming gesture.","learningMoment":"a young Santhal child classmate showing warmth, inclusion, and building a strong social bond.","meaning":"My name is Santhal.","meaning_en":"My name is Santhal.","meaning_bn":"আমার নাম সাঁওতাল।","pronunciation":"Injaag nyutum do Santhal.","meaning_hi":"मेरा नाम संथाल है.","meaning_or":"ମୋର ନାମ ସନ୍ଥାଲ |"}},{"id":"","order":2,"type":"text","markdown":"Am do okatem chalag kana?","textOlChiki":"ᱟᱢ ᱫᱚ ᱚᱠᱟᱛᱮᱢ ᱪᱟᱞᱟᱜ ᱠᱟᱱᱟ?","textLatin":"Am do okatem chalag kana?","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_basics_2/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_basics_2/view?project=699495910038e39622c5","textBengali":"আম দ অকাতেম চালাঃ কানা?","textHindi":"आम द अकातेम चालाग काना?","textOdia":"ଆମ ଦ ଅକାତେମ ଚାଲାଗ କାନା?","emotion":"Kindness","storyArc":"Exploring Nature","growthValue":"Learning","characterGoal":"Explore nature","imageDirection":"Olitun stands beside a traditional home, pointing happily at a colorful detail on the hand-painted wall. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Gentle smile, soft eyes, hands offering help or gesturing politely with care.","learningMoment":"Olitun putting empathy into action