INSERT OR REPLACE INTO lessons (id, category_id, title_ol_chiki, title_latin, lesson_type, order_index, raw_json) VALUES ('lesson_sentences_complex_beginner', 'cat_sentences_1778594024495', 'ᱢᱩᱞ ᱜᱟᱞᱢᱟᱨᱟᱣ', 'Simple Dialogues & Routines', NULL, 0, '{"id":"lesson_sentences_complex_beginner","categoryId":"cat_sentences_1778594024495","titleOlChiki":"ᱢᱩᱞ ᱜᱟᱞᱢᱟᱨᱟᱣ","titleLatin":"Simple Dialogues & Routines","level":"beginner","orderIndex":0,"isActive":true,"estimatedMinutes":5,"description":"","thumbnailUrl":null,"isPremium":false,"audioUrl":null,"blocks":[{"id":"","order":0,"type":"text","markdown":"Sagun setag baba, am ched leka menama?","textOlChiki":"ᱥᱟᱹᱜᱩᱱ ᱥᱮᱛᱟᱜ ᱵᱟᱵᱟ, ᱟᱢ ᱪᱮᱫ ᱞᱮᱠᱟ ᱢᱮᱱᱟᱢᱟ?","textLatin":"Sagun setag baba, am ched leka menama?","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_0/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_0/view?project=699495910038e39622c5","textBengali":"সাগুন সেতাঃ বাবা, আম চেদ লেকা মেনামা?","textHindi":"सागुन सेताग बाबा, आम चेद लेका मेनामा?","textOdia":"ସାଗୁନ ସେତାଗ ବାବା, ଆମ ଚେଦ ଲେକା ମେନାମା?","emotion":"Confidence","storyArc":"Learning New Things","growthValue":"Learning","characterGoal":"Complete a task","imageDirection":"A kind, tall Santhal father and Olitun standing side-by-side, sharing a warm moment as they look over a project. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Standing tall, head held high, chest slightly out, a bright and self-assured smile.","learningMoment":"Olitun exhibiting self-reliance, readiness to learn, and pride in their capabilities.","meaning":"Good morning father, how are you?","meaning_en":"Good morning father, how are you?","meaning_bn":"সুপ্রভাত বাবা, তুমি কেমন আছো?","pronunciation":"Sagun setag baba, am ched leka menama?","meaning_hi":"शुभ प्रभात पिताजी, आप कैसे हैं?","meaning_or":"ଶୁଭ ସକାଳ ବାପା, ତୁମେ କେମିତି ଅଛ?"}},{"id":"","order":1,"type":"text","markdown":"In do napay ge menanja, am ched em chikayeda?","textOlChiki":"ᱤᱧ ᱫᱚ ᱱᱟᱯᱟᱭ ᱜᱮ ᱢᱮᱱᱟᱧᱟ, ᱟᱢ ᱪᱮᱫ ᱮᱢ ᱪᱤᱠᱟᱹᱭᱮᱫᱟ?","textLatin":"In do napay ge menanja, am ched em chikayeda?","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_1/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_1/view?project=699495910038e39622c5","textBengali":"ইঞ দ নাপায় গে মেনাঞা, আম চেদ এম চিকায়েদা?","textHindi":"इञ द नापाय गे मेनाञा, आम चेद एम चिकायेदा?","textOdia":"ଇଞ ଦ ନାପାୟ ଗେ ମେନାଞା, ଆମ ଚେଦ ଏମ ଚିକାୟେଦା?","emotion":"Gratitude","storyArc":"Helping Others","growthValue":"Confidence","characterGoal":"Practice communication","imageDirection":"Olitun points to a chalkboard showing simple diagrams, looking encouragingly toward classmates. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Slightly bowed head, hands held together or offering a token of appreciation, warm smile.","learningMoment":"Olitun acknowledging and appreciating the kindness and efforts of others.","meaning":"I am doing well, what are you doing?","meaning_en":"I am doing well, what are you doing?","meaning_bn":"আমি ভালো আছি, তুমি কী করছো?","pronunciation":"In do napay ge menanja, am ched em chikayeda?","meaning_hi":"मैं ठीक हूँ, तुम क्या कर रहे हो?","meaning_or":"ମୁଁ ଭଲ ଅଛି, ତୁମେ କ’ଣ କରୁଛ?"}},{"id":"","order":2,"type":"text","markdown":"In do Ol Chiki chedog kananj.","textOlChiki":"ᱤᱧ ᱫᱚ ᱚᱞ ᱪᱤᱠᱤ ᱪᱮᱫᱚᱜ ᱠᱟᱹᱱᱟᱹᱧ।","textLatin":"In do Ol Chiki chedog kananj.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_2/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_2/view?project=699495910038e39622c5","textBengali":"ইঞ দ অল চিকি চেদঃ কানাঞ।","textHindi":"इञ द अल चिकि चेदग कानाञ।","textOdia":"ଇଞ ଦ ଅଲ ଚିକି ଚେଦଗ କାନାଞ।","emotion":"Responsibility","storyArc":"Building Confidence","growthValue":"Responsibility","characterGoal":"Build confidence","imageDirection":"a young Santhal child classmate works carefully on a drawing page spread out on a wooden table, focused and happy. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Focused and attentive expression, steady hands working carefully, steady stance.","learningMoment":"a young Santhal child classmate taking charge of duties, caring for the environment or community.","meaning":"I am learning Ol Chiki.","meaning_en":"I am learning Ol Chiki.","meaning_bn":"আমি অলচিকি শিখছি।","pronunciation":"In do Ol Chiki chedog kananj.","meaning_hi":"मैं ओल चिकी सीख रहा हूँ।","meaning_or":"ମୁଁ ଅଲ୍ ଚିକି ଶିଖୁଛି।"}},{"id":"","order":3,"type":"text","markdown":"Nowa do adi napay katha kana, sarhaw.","textOlChiki":"ᱱᱚᱶᱟ ᱫᱚ ᱟᱹᱰᱤ ᱱᱟᱯᱟᱭ ᱠᱟᱛᱷᱟ ᱠᱟᱱᱟ, ᱥᱟᱨᱦᱟᱣ।","textLatin":"Nowa do adi napay katha kana, sarhaw.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_3/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_3/view?project=699495910038e39622c5","textBengali":"নওয়া দ আডি নাপায় কাথা কানা, সারহাও।","textHindi":"नोवा द आडि नापाय काथा काना, सारहाव।","textOdia":"ନୋୱା ଦ ଆଡି ନାପାୟ କାଥା କାନା, ସାରହାୱ।","emotion":"Confidence","storyArc":"Learning New Things","growthValue":"Learning","characterGoal":"Help someone","imageDirection":"a young Santhal child classmate stands tall in a schoolyard, holding a new notebook and smiling with pride. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Standing tall, head held high, chest slightly out, a bright and self-assured smile.","learningMoment":"a young Santhal child classmate exhibiting self-reliance, readiness to learn, and pride in their capabilities.","meaning":"This is very good , I appreciate!","meaning_en":"This is very good , I appreciate!","meaning_bn":"এটি খুব ভাল কথা, আমি প্রশংসা করি!","pronunciation":"Nowa do adi napay katha kana, sarhaw.","meaning_hi":"ये बहुत अच्छी बात है। मैं इसकी सराहना करता हूँ।","meaning_or":"ଏହା ବହୁତ ଭଲ କଥା ଅଟେ। ମୁଁ ଏହାକୁ ପ୍ରଶଂସା କରୁଛି।"}},{"id":"","order":4,"type":"text","markdown":"Amaag orag do oka atu re menag aa?","textOlChiki":"ᱟᱢᱟᱜ ᱚᱲᱟᱜ ᱫᱚ ᱚᱠᱟ ᱟᱹᱛᱩ ᱨᱮ ᱢᱮᱱᱟᱜᱼᱟ?","textLatin":"Amaag orag do oka atu re menag aa?","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_4/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_4/view?project=699495910038e39622c5","textBengali":"আমাঃ অড়াঃ দ অকা আতু রে মেনাঃ আ?","textHindi":"आमाग अड़ाग द अका आतु रे मेनाग आ?","textOdia":"ଆମାଗ ଅଡ଼ାଗ ଦ ଅକା ଆତୁ ରେ ମେନାଗଆ?","emotion":"Gratitude","storyArc":"Helping Others","growthValue":"Confidence","characterGoal":"Complete a task","imageDirection":"Olitun proudly holds a hand-painted wooden sign, smiling warmly with confidence. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Slightly bowed head, hands held together or offering a token of appreciation, warm smile.","learningMoment":"Olitun acknowledging and appreciating the kindness and efforts of others.","meaning":"In which village is your home located?","meaning_en":"In which village is your home located?","meaning_bn":"আপনার বাড়ি কোন গ্রামে?","pronunciation":"Amaag orag do oka atu re menag aa?","meaning_hi":"आपका घर किस गाँव में स्थित है?","meaning_or":"ଆପଣଙ୍କ ଘର କେଉଁ ଗାଁରେ ଅବସ୍ଥିତ?"}},{"id":"","order":5,"type":"text","markdown":"Injaag orag do adi napay atu re menag aa.","textOlChiki":"ᱤᱧᱟᱜ ᱚᱲᱟᱜ ᱫᱚ ᱟᱹᱰᱤ ᱱᱟᱯᱟᱭ ᱟᱹᱛᱩ ᱨᱮ ᱢᱮᱱᱟᱜᱼᱟ।","textLatin":"Injaag orag do adi napay atu re menag aa.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_5/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_5/view?project=699495910038e39622c5","textBengali":"ইঞাঃ অড়াঃ দ আডি নাপায় আতু রে মেনাঃ আ।","textHindi":"इञाग अड़ाग द आडि नापाय आतु रे मेनागआ।","textOdia":"ଇଞାଗ ଅଡ଼ାଗ ଦ ଆଡି ନାପାୟ ଆତୁ ରେ ମେନାଗଆ।","emotion":"Responsibility","storyArc":"Building Confidence","growthValue":"Responsibility","characterGoal":"Practice communication","imageDirection":"a young Santhal child classmate points to a chalkboard showing simple diagrams, looking encouragingly toward classmates. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Focused and attentive expression, steady hands working carefully, steady stance.","learningMoment":"a young Santhal child classmate taking charge of duties, caring for the environment or community.","meaning":"My home is in a very beautiful village.","meaning_en":"My home is in a very beautiful village.","meaning_bn":"আমার বাড়ি খুব সুন্দর গ্রামে।","pronunciation":"Injaag orag do adi napay atu re menag aa.","meaning_hi":"मेरा घर एक बहुत ही खूबसूरत गांव में है.","meaning_or":"ମୋ ଘର ବହୁତ ସୁନ୍ଦର ଗାଁରେ ଅଛି |"}},{"id":"","order":6,"type":"text","markdown":"Tehenj do alom kamiya, jirag me.","textOlChiki":"ᱛᱮᱦᱮᱧ ᱫᱚ ᱟᱞᱚᱢ ᱠᱟᱹᱢᱤᱭᱟ, ᱡᱤᱨᱟᱹᱜ ᱢᱮ।","textLatin":"Tehenj do alom kamiya, jirag me.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_6/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_6/view?project=699495910038e39622c5","textBengali":"তেহেঞ দ আলম কামিয়া, জিরৌঃ মে।।","textHindi":"तेहेञ द आलम कामिया, जिराग मे।","textOdia":"ତେହେଞ ଦ ଆଲମ କାମିୟା, ଜିରାଗ ମେ।","emotion":"Confidence","storyArc":"Learning New Things","growthValue":"Learning","characterGoal":"Build confidence","imageDirection":"Olitun carefully carrying out a task, like neatly filing books or designing a wooden model. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Standing tall, head held high, chest slightly out, a bright and self-assured smile.","learningMoment":"Olitun exhibiting self-reliance, readiness to learn, and pride in their capabilities.","meaning":"Do not work today, take rest.","meaning_en":"Do not work today, take rest.","meaning_bn":"আজ কাজ করবেন না, বিশ্রাম নিন।","pronunciation":"Tehenj do alom kamiya, jirag me.","meaning_hi":"आज काम न करें, आराम करें.","meaning_or":"ଆଜି କାମ କର ନାହିଁ, ବିଶ୍ରାମ ନିଅ |"}},{"id":"","order":7,"type":"text","markdown":"Daya kate nonde hijug me, daka jom me.","textOlChiki":"ᱫᱟᱭᱟ ᱠᱟᱛᱮ ᱱᱚᱸᱰᱮ ᱦᱤᱡᱩᱜ ᱢᱮ, ᱫᱟᱠᱟ ᱡᱚᱢ ᱢᱮ।","textLatin":"Daya kate nonde hijug me, daka jom me.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_7/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_7/view?project=699495910038e39622c5","textBengali":"দায়া কাতে নঁডে হিজুঃ মে, দাকা জম মে।","textHindi":"दाया काते नँडे हिजुग मे, दाका जम मे।","textOdia":"ଦାୟା କାତେ ନଁଡେ ହିଜୁଗ ମେ, ଦାକା ଜମ ମେ।","emotion":"Gratitude","storyArc":"Helping Others","growthValue":"Responsibility","characterGoal":"Help someone","imageDirection":"a young Santhal child classmate stands tall in a schoolyard, holding a new notebook and smiling with pride. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Slightly bowed head, hands held together or offering a token of appreciation, warm smile.","learningMoment":"a young Santhal child classmate acknowledging and appreciating the kindness and efforts of others.","meaning":"Please come here and eat food.","meaning_en":"Please come here and eat food.","meaning_bn":"দয়া করে এখানে এসে খাবার খান।","pronunciation":"Daya kate nonde hijug me, daka jom me.","meaning_hi":"कृपया यहीं आकर भोजन करें।","meaning_or":"ଦୟାକରି ଏଠାକୁ ଆସ ଏବଂ ଖାଦ୍ୟ ଖାଅ |"}},{"id":"","order":8,"type":"text","markdown":"In do dag nju sananj kana, dag emanj me.","textOlChiki":"ᱤᱧ ᱫᱚ ᱫᱟᱜ ᱧᱩ ᱥᱟᱱᱟᱧ ᱠᱟᱱᱟ, ᱫᱟᱜ ᱮᱢᱟᱧ ᱢᱮ।","textLatin":"In do dag nju sananj kana, dag emanj me.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_8/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_8/view?project=699495910038e39622c5","textBengali":"ইঞ দ দাঃ ঞু সানাঞ কানা, দাঃ এমাঞ মে।","textHindi":"इञ द दाग ञु सानाञ काना, दाग एमाञ मे।","textOdia":"ଇଞ ଦ ଦାଗ ଞୁ ସାନାଞ କାନା, ଦାଗ ଏମାଞ ମେ।","emotion":"Gratitude","storyArc":"Helping Others","growthValue":"Responsibility","characterGoal":"Help someone","imageDirection":"a young Santhal child classmate drinking cool, clean water from a traditional clay pot, looking refreshed and happy. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Slightly bowed head, hands held together or offering a token of appreciation, warm smile.","learningMoment":"a young Santhal child classmate acknowledging and appreciating the kindness and efforts of others.","meaning":"I want to drink water, please give me water.","meaning_en":"I want to drink water, please give me water.","meaning_bn":"আমি জল খেতে চাই, দয়া করে আমাকে জল দিন।","pronunciation":"In do dag nju sananj kana, dag emanj me.","meaning_hi":"मैं पानी पीना चाहता हूं, कृपया मुझे पानी दीजिए।","meaning_or":"ମୁଁ ପାଣି ପିଇବାକୁ ଚାହୁଁଛି, ଦୟାକରି ମୋତେ ପାଣି ଦିଅ |"}},{"id":"","order":9,"type":"text","markdown":"Atu reyag hor do adi jilinj geya.","textOlChiki":"ᱟᱹᱛᱩ ᱨᱮᱭᱟᱜ ᱦᱚᱨ ᱫᱚ ᱟᱹᱰᱤ ᱡᱤᱞᱤᱧ ᱜᱮᱭᱟ।","textLatin":"Atu reyag hor do adi jilinj geya.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_9/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_9/view?project=699495910038e39622c5","textBengali":"আতু রেয়াঃ হর দ আডি জিলিঞ গেয়া।","textHindi":"आतु रेयाग हर द आडि जिलिञ गेया।","textOdia":"ଆତୁ ରେୟାଗ ହର ଦ ଆଡି ଜିଲିଞ ଗେୟା।","emotion":"Confidence","storyArc":"Learning New Things","growthValue":"Learning","characterGoal":"Practice communication","imageDirection":"a young Santhal child classmate points to a chalkboard showing simple diagrams, looking encouragingly toward classmates. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Standing tall, head held high, chest slightly out, a bright and self-assured smile.","learningMoment":"a young Santhal child classmate exhibiting self-reliance, readiness to learn, and pride in their capabilities.","meaning":"The village road is very long.","meaning_en":"The village road is very long.","meaning_bn":"গ্রামের রাস্তা অনেক লম্বা।","pronunciation":"Atu reyag hor do adi jilinj geya.","meaning_hi":"गांव की सड़क बहुत लंबी है.","meaning_or":"ଗାଁ ରାସ୍ତା ବହୁତ ଲମ୍ବା ଅଟେ |"}},{"id":"","order":10,"type":"text","markdown":"Aam ayo ar baba do okare menag kina?","textOlChiki":"ᱟᱢ ᱟᱭᱳ ᱟᱨ ᱵᱟᱵᱟ ᱫᱚ ᱚᱠᱟᱨᱮ ᱢᱮᱱᱟᱜ ᱠᱤᱱᱟ?","textLatin":"Aam ayo ar baba do okare menag kina?","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_10/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_10/view?project=699495910038e39622c5","textBengali":"আম আয়ো আর বাবা দ অকারে মেনাঃ কিনা?","textHindi":"आम आयो आर बाबा द अकारे मेनाग किना?","textOdia":"ଆମ ଆୟୋ ଆର ବାବା ଦ ଅକାରେ ମେନାଗ କିନା?","emotion":"Gratitude","storyArc":"Helping Others","growthValue":"Confidence","characterGoal":"Build confidence","imageDirection":"A kind, tall Santhal father and Olitun standing side-by-side, sharing a warm moment as they look over a project. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Slightly bowed head, hands held together or offering a token of appreciation, warm smile.","learningMoment":"Olitun acknowledging and appreciating the kindness and efforts of others.","meaning":"Where are your mother and father?","meaning_en":"Where are your mother and father?","meaning_bn":"তোমার মা বাবা কোথায়?","pronunciation":"Aam ayo ar baba do okare menag kina?","meaning_hi":"तुम्हारे माता-पिता कहाँ हैं?","meaning_or":"ତୁମର ମା ଏବଂ ବାପା କେଉଁଠାରେ ଅଛନ୍ତି?"}},{"id":"","order":11,"type":"text","markdown":"Unkin do orag re ge menag kina.","textOlChiki":"ᱩᱱᱠᱤᱱ ᱫᱚ ᱚᱲᱟᱜ ᱨᱮ ᱜᱮ ᱢᱮᱱᱟᱜ ᱠᱤᱱᱟ।","textLatin":"Unkin do orag re ge menag kina.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_11/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_11/view?project=699495910038e39622c5","textBengali":"উনকিন দ অড়াঃ রে গে মেনাঃ কিনা।","textHindi":"उनकिन द अड़ाग रे गे मेनाग किना।","textOdia":"ଉନକିନ ଦ ଅଡ଼ାଗ ରେ ଗେ ମେନାଗ କିନା।","emotion":"Responsibility","storyArc":"Building Confidence","growthValue":"Responsibility","characterGoal":"Help someone","imageDirection":"a young Santhal child classmate pointing toward a balanced, hand-carved wooden scale, indicating fairness and justice. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Focused and attentive expression, steady hands working carefully, steady stance.","learningMoment":"a young Santhal child classmate taking charge of duties, caring for the environment or community.","meaning":"They are right at home.","meaning_en":"They are right at home.","meaning_bn":"তারা বাড়িতে আছে।","meaning_hi":"वे  घर पर हैं.","meaning_or":"ସେମାନେ କ''ଣ ଘରେ ଅଛନ୍ତି? |"}},{"id":"","order":12,"type":"text","markdown":"Inij misra do itun asra te chalag kanay.","textOlChiki":"ᱤᱧᱤᱡ ᱢᱤᱥᱨᱟ ᱫᱚ ᱤᱛᱩᱱ ᱟᱥᱲᱟ ᱛᱮ ᱪᱟᱞᱟᱜ ᱠᱟᱱᱟᱭ।","textLatin":"Inij misra do itun asra te chalag kanay.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_12/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_12/view?project=699495910038e39622c5","textBengali":"ইঞিজ মিসরা দ ইতুন আসড়া তে চালাঃ কানায়।","textHindi":"इञिज मिसरा द इतुन आसड़ा ते चालाग कानाय।","textOdia":"ଇଞିଜ ମିସରା ଦ ଇତୁନ ଆସଡ଼ା ତେ ଚାଲାଗ କାନାୟ।","emotion":"Confidence","storyArc":"Learning New Things","growthValue":"Learning","characterGoal":"Build confidence","imageDirection":"a young Santhal child classmate sitting beside a younger sister, helping her write a word on a clean sand board with pride. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Standing tall, head held high, chest slightly out, a bright and self-assured smile.","learningMoment":"a young Santhal child classmate exhibiting self-reliance, readiness to learn, and pride in their capabilities.","meaning":"My younger sister is going to school.","meaning_en":"My younger sister is going to school.","meaning_bn":"আমার ছোট বোন স্কুলে যাচ্ছে।","pronunciation":"Inij misra do itun asra te chalag kanay.","meaning_hi":"मेरी छोटी बहन स्कूल जा रही है.","meaning_or":"ମୋର ସାନ ଭଉଣୀ ବିଦ୍ୟାଳୟକୁ ଯାଉଛନ୍ତି |"}},{"id":"","order":13,"type":"text","markdown":"Tehenj do Singe maha kana, chhuti maha kana.","textOlChiki":"ᱛᱮᱦᱮᱧ ᱫᱚ ᱥᱤᱸᱜᱮ ᱢᱟᱦᱟ ᱠᱟᱱᱟ, ᱪᱷᱩᱴᱤ ᱢᱟᱦᱟ ᱠᱟᱱᱟ।","textLatin":"Tehenj do Singe maha kana, chhuti maha kana.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_13/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_beginner_13/view?project=699495910038e39622c5","textBengali":"তেহেঞ দ সিঁগে মাহা কানা, ছুটি মাহা কানা।","textHind