INSERT OR REPLACE INTO lessons (id, category_id, title_ol_chiki, title_latin, lesson_type, order_index, raw_json) VALUES ('lesson_sentences_complex_intermed', 'cat_sentences_1778594024495', 'ᱟᱹᱛᱩ ᱨᱮᱭᱟᱜ ᱜᱟᱞᱢᱟᱨᱟᱣ', 'Village & Social Life', NULL, 0, '{"id":"lesson_sentences_complex_intermed","categoryId":"cat_sentences_1778594024495","titleOlChiki":"ᱟᱹᱛᱩ ᱨᱮᱭᱟᱜ ᱜᱟᱞᱢᱟᱨᱟᱣ","titleLatin":"Village & Social Life","level":"beginner","orderIndex":0,"isActive":true,"estimatedMinutes":5,"description":"","thumbnailUrl":null,"isPremium":false,"audioUrl":null,"blocks":[{"id":"","order":0,"type":"text","markdown":"Atu rin hor do jaher than re ko jawra akana.","textOlChiki":"ᱟᱹᱛᱩ ᱨᱤᱱ ᱦᱚᱲ ᱫᱚ ᱡᱟᱦᱮᱨ ᱛᱷᱟᱱ ᱨᱮ ᱠᱚ ᱡᱟᱣᱨᱟ ᱟᱠᱟᱱᱟ।","textLatin":"Atu rin hor do jaher than re ko jawra akana.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_0/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_0/view?project=699495910038e39622c5","textBengali":"আতু রিন হড় দ জাহের থান রে ক জাওয়রা আকানা।","textHindi":"आतु रिन हड़ द जाहेर थान रे क जावरा आकाना।","textOdia":"ଆତୁ ରିନ ହଡ଼ ଦ ଜାହେର ଥାନ ରେ କ ଜାୱରା ଆକାନା।","emotion":"Pride","storyArc":"Working Together","growthValue":"Leadership","characterGoal":"Solve a problem","imageDirection":"Olitun holds a ripe, bright red pomegranate, showing its rich color with a proud and happy smile. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Standing proud and tall, head high, shoulders back, holding cultural artifacts or projects.","learningMoment":"Olitun celebrating cultural identity, heritage, and personal achievements.","meaning":"The villagers have gathered at the Jaher Than.","pronunciation":"Atu rin hor do jaher than re ko jawra akana.","meaning_en":"The villagers have gathered at the Jaher Than.","meaning_bn":"গ্রামবাসীরা জাহের থানে সমবেত হয়েছেন।","meaning_hi":"गाँव वाले जाहेर थान में इकट्ठा हुए हैं।","meaning_or":"ଗାଁ ଲୋକମାନେ ଜାହେର ଥାନରେ ଏକାଠି ହୋଇଛନ୍ତି।"}},{"id":"","order":1,"type":"text","markdown":"Majhi Hadam do atu hor saw e galmaraw kana.","textOlChiki":"ᱢᱟᱹᱡᱷᱤ ᱦᱟᱲᱟᱢ ᱫᱚ ᱟᱹᱛᱩ ᱦᱚᱲ ᱥᱟᱶ ᱮ ᱜᱟᱞᱢᱟᱨᱟᱣ ᱠᱟᱱᱟ।","textLatin":"Majhi Hadam do atu hor saw e galmaraw kana.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_1/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_1/view?project=699495910038e39622c5","textBengali":"মাঝি হাড়াম দ আতু হড় সাও এ গালমারাও কানা।","textHindi":"माझि हाड़ाम द आतु हड़ साव ए गालमाराव काना।","textOdia":"ମାଝି ହାଡ଼ାମ ଦ ଆତୁ ହଡ଼ ସାୱ ଏ ଗାଲମାରାୱ କାନା।","emotion":"Achievement","storyArc":"Exploring Nature","growthValue":"Creativity","characterGoal":"Teach others","imageDirection":"a young Santhal child classmate gestures toward a village map drawn on a board, explaining a plan to classmates with confidence. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Cheerful smile, hands raised in a small celebration or showing a finished project.","learningMoment":"a young Santhal child classmate enjoying the reward of dedication, effort, and hard work.","meaning":"The Majhi Hadam is talking with the villagers.","pronunciation":"Majhi Hadam do atu hor saw e galmaraw kana.","meaning_en":"The Majhi Hadam is talking with the villagers.","meaning_bn":"গ্রামের মাঝি হাড়াম গ্রামবাসীদের সাথে কথা বলছেন।","meaning_hi":"माझी हराम ग्रामीणों से बात कर रहे हैं।","meaning_or":"ମାଝି ହାରାମ ଗାଁ ଲୋକମାନଙ୍କ ସହିତ କଥା ହେଉଛନ୍ତି।"}},{"id":"","order":2,"type":"text","markdown":"Tehenj do adi napay Santali serenj ko serenj eda.","textOlChiki":"ᱛᱮᱦᱮᱧ ᱫᱚ ᱟᱹᱰᱤ ᱱᱟᱯᱟᱭ ᱥᱟᱱᱛᱟᱲᱤ ᱥᱮᱨᱮᱧ ᱠᱚ ᱥᱮᱨᱮᱧ ᱮᱫᱟ।","textLatin":"Tehenj do adi napay Santali serenj ko serenj eda.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_2/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_2/view?project=699495910038e39622c5","textBengali":"তেহেঞ দ আডি নাপায় সানতাড়ি সেরেঞ ক সেরেঞ এদা।","textHindi":"तेहेञ द आडि नापाय सानताड़ि सेरेञ क सेरेञ एदा।","textOdia":"ତେହେଞ ଦ ଆଡି ନାପାୟ ସାନତାଡ଼ି ସେରେଞ କ ସେରେଞ ଏଦା।","emotion":"Gratitude","storyArc":"Dreaming Big","growthValue":"Problem Solving","characterGoal":"Create something useful","imageDirection":"Olitun playing a traditional hand-drum (tumdak) with an energetic, rhythmic posture and a wide smile. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Slightly bowed head, hands held together or offering a token of appreciation, warm smile.","learningMoment":"Olitun acknowledging and appreciating the kindness and efforts of others.","meaning":"Today they are singing very beautiful Santali songs.","pronunciation":"Tehenj do adi napay Santali serenj ko serenj eda.","meaning_en":"Today they are singing very beautiful Santali songs.","meaning_bn":"আজ তারা খুব সুন্দর সাঁওতালি গান গাইছেন।","meaning_hi":"आज वे बहुत सुंदर संताली गीत गा रहे हैं।","meaning_or":"ଆଜି ସେମାନେ ବହୁତ ସୁନ୍ଦର ସାନ୍ତାଳୀ ଗୀତ ଗାଉଛନ୍ତି।"}},{"id":"","order":3,"type":"text","markdown":"Dare umul re durub kate unku ko jiraw kana.","textOlChiki":"ᱫᱟᱨᱮ ᱩᱢᱩᱞ ᱨᱮ ᱫᱩᱲᱩᱵ ᱠᱟᱛᱮ ᱩᱱᱠᱩ ᱠᱚ ᱡᱤᱨᱟᱹᱣ ᱠᱟᱱᱟ।","textLatin":"Dare umul re durub kate unku ko jiraw kana.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_3/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_3/view?project=699495910038e39622c5","textBengali":"দারে উমুল রে দুড়ুব কাতে উনকু ক জিরৌঃ কানা।","textHindi":"दारे उमुल रे दुड़ुब काते उनकु क जिराव काना।","textOdia":"ଦାରେ ଉମୁଲ ରେ ଦୁଡ଼ୁବ କାତେ ଉନକୁ କ ଜିରାୱ କାନା।","emotion":"Pride","storyArc":"Working Together","growthValue":"Leadership","characterGoal":"Solve a problem","imageDirection":"a young Santhal child classmate planting a young green seedling in rich soil, showing care and responsibility for nature. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Standing proud and tall, head high, shoulders back, holding cultural artifacts or projects.","learningMoment":"a young Santhal child classmate celebrating cultural identity, heritage, and personal achievements.","meaning":"Sitting under the tree''s shade, they are resting.","pronunciation":"Dare umul re durub kate unku ko jiraw kana.","meaning_en":"Sitting under the tree''s shade, they are resting.","meaning_bn":"গাছের ছায়ায় বসে তারা বিশ্রাম নিচ্ছে।","meaning_hi":"वे पेड़ की छाया में बैठकर आराम कर रहे हैं।","meaning_or":"ଗଛର ଛାଇ ତଳେ ବସି ସେମାନେ ବିଶ୍ରାମ ନେଉଛନ୍ତି |"}},{"id":"","order":4,"type":"text","markdown":"Am do tumdah ar tamak ru em badaya?","textOlChiki":"ᱟᱢ ᱫᱚ ᱛᱩᱢᱫᱟᱜ ᱟᱨ ᱴᱟᱢᱟᱠ ᱨᱩ ᱮᱢ ᱵᱟᱰᱟᱭᱟ?","textLatin":"Am do tumdah ar tamak ru em badaya?","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_4/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_4/view?project=699495910038e39622c5","textBengali":"আম দ তুমদাঃ আর টামাক রু এম বাডায়া?","textHindi":"आम द तुमदाग आर टामाक रु एम बाडाया?","textOdia":"ଆମ ଦ ତୁମଦାଗ ଆର ଟାମାକ ରୁ ଏମ ବାଡାୟା?","emotion":"Achievement","storyArc":"Working Together","growthValue":"Creativity","characterGoal":"Create something useful","imageDirection":"Olitun holding a handful of rich, dark soil, ready to plant seeds, looking hopeful and proud. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Cheerful smile, hands raised in a small celebration or showing a finished project.","learningMoment":"Olitun enjoying the reward of dedication, effort, and hard work.","meaning":"Do you know how to play  tumdah and tamak?","pronunciation":"Am do tumdah ar tamak ru em badaya?","meaning_en":"Do you know how to play  tumdah and tamak?","meaning_bn":"তুমি কী তুমদাঃ আর টামাক বাজাতে জানো?","meaning_hi":"क्या तुम्हें टुमदा और तमाक बजाना आता है?","meaning_or":"ତୁମେ କ''ଣ ଟୁମଦା ଏବଂ ତମାକ୍ ବଜାଇବା ଜାଣ?"}},{"id":"","order":5,"type":"text","markdown":"Hẽ, in do tumdag ru adi napay inj badaya.","textOlChiki":"ᱦᱮᱸ, ᱤᱧ ᱫᱚ ᱛᱩᱢᱫᱟᱜ ᱨᱩ ᱟᱹᱰᱤ ᱱᱟᱯᱟᱭ ᱤᱧ ᱵᱟᱰᱟᱭᱟ।","textLatin":"Hẽ, in do tumdag ru adi napay inj badaya.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_5/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_5/view?project=699495910038e39622c5","textBengali":"হেঁ, ইঞ দ তুমদাঃ রু আডি নাপায় ইঞ বাডায়া।","textHindi":"हेँ, इञ द तुमदाग रु आडि नापाय इञ बाडाया।","textOdia":"ହେଁ, ଇଞ ଦ ତୁମଦାଗ ରୁ ଆଡି ନାପାୟ ଇଞ ବାଡାୟା","emotion":"Achievement","storyArc":"Working Together","growthValue":"Creativity","characterGoal":"Create something useful","imageDirection":"Olitun holding a handful of rich, dark soil, ready to plant seeds, looking hopeful and proud. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Cheerful smile, hands raised in a small celebration or showing a finished project.","learningMoment":"Olitun enjoying the reward of dedication, effort, and hard work.","meaning":"Yes, I know how to play tumdah very well.","pronunciation":"Hẽ, in do tumdag ru adi napay inj badaya.","meaning_en":"Yes, I know how to play tumdah very well.","meaning_bn":"হ্যাঁ, আমি তুমদাঃ ভালো বাজাতে জানি।","meaning_hi":"हाँ, मैं मिट्टी का ढोल बहुत अच्छी तरह बजाना जानता हूँ।","meaning_or":"ହଁ, ମୁଁ ଜାଣେ କିପରି ମାଟି ଡ୍ରମ୍ ବଜାଇବି |"}},{"id":"","order":6,"type":"text","markdown":"Langde enej lagid kuri ar kora ko sapraw akana.","textOlChiki":"ᱞᱟᱜᱽᱬᱮ ᱮᱱᱮᱡ ᱞᱟᱹᱜᱤᱫ ᱠᱩᱲᱤ ᱟᱨ ᱠᱚᱲᱟ ᱠᱚ ᱥᱟᱯᱲᱟᱣ ᱟᱠᱟᱱᱟ।","textLatin":"Langde enej lagid kuri ar kora ko sapraw akana.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_6/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_6/view?project=699495910038e39622c5","textBengali":"লাগড়ে এনেজ লাগিদ কুড়ি আর কড়া ক সাপড়াওয় আকানা।","textHindi":"लागड़े एनेज लागिद कुड़ि आर कड़ा क सापड़ाव आकाना।","textOdia":"ଲାଗ୍ଞେ ଏନେଜ୍ ଲାଗିଦ୍ କୁଡ଼ି ଆର୍ କୋଡ଼ା କୋ ସାପ୍ରାଓ୍ ଆକାନା।","emotion":"Achievement","storyArc":"Working Together","growthValue":"Creativity","characterGoal":"Create something useful","imageDirection":"Olitun excitedly discovering knowledge inside a large, open picture book that glows with colorful patterns. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Cheerful smile, hands raised in a small celebration or showing a finished project.","learningMoment":"Olitun enjoying the reward of dedication, effort, and hard work.","meaning":"The boys and girls are ready for the Langde dance.","pronunciation":"Langde enej lagid kuri ar kora ko sapraw akana.","meaning_en":"The boys and girls are ready for the Langde dance.","meaning_bn":"ছেলে-মেয়েরা লাঁগড়ে নাচের জন্য প্রস্তুত।","meaning_hi":"लागड़े नृत्य के लिए लड़कियाँ और लड़के सज-धज कर तैयार हैं।","meaning_or":"ଲାଗଡ଼େ ନାଚ ପାଇଁ ଝିଅ ଓ ପୁଅମାନେ ସଜବାଜ ହୋଇଛନ୍ତି। |"}},{"id":"","order":7,"type":"text","markdown":"Ale atu re do adi marang Baha porob huyuga.","textOlChiki":"ᱟᱞᱮ ᱟᱹᱛᱩ ᱨᱮ ᱫᱚ ᱟᱹᱰᱤ ᱢᱟᱨᱟᱝ ᱵᱟᱦᱟ ᱯᱚᱨᱚᱵ ᱦᱩᱭᱩᱜᱼᱟ।","textLatin":"Ale atu re do adi marang Baha porob huyuga.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_7/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_7/view?project=699495910038e39622c5","textBengali":"আলে আতু রে দ আডি মারাং বাহা পরব হুয়ুঃ আ।","textHindi":"आले आतु रे द आडि माराङ बाहा परब हुयुग आ।","textOdia":"ଆଲେ ଆତୁ ରେ ଦ ଆଡି ମାରାଙ ବାହା ପରବ ହୁୟୁଗଆ","emotion":"Achievement","storyArc":"Exploring Nature","growthValue":"Creativity","characterGoal":"Teach others","imageDirection":"a young Santhal child classmate stands proudly at a crossroads in the village, pointing toward a path of opportunity. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":"Cheerful smile, hands raised in a small celebration or showing a finished project.","learningMoment":"a young Santhal child classmate enjoying the reward of dedication, effort, and hard work.","meaning":"A very grand Baha festival is celebrated in our village.","pronunciation":"Ale atu re do adi marang Baha porob huyug aa.","meaning_en":"A very grand Baha festival is celebrated in our village.","meaning_bn":"আমাদের গ্রামে একটি খুব জমকালো বাহা উৎসব পালিত হয়।","meaning_hi":"हमारे गांव में बहुत भव्य बाहा पर्व मनाया जाता है.","meaning_or":"ଆମ ଗାଁରେ ଏକ ବହୁତ ବଡ ବାହା ପର୍ବ ପାଳନ କରାଯାଏ |"}},{"id":"","order":8,"type":"text","markdown":"Sarjom baha te kuri ko bohog ko sajaw eda.","textOlChiki":"ᱥᱟᱨᱡᱚᱢ ᱵᱟᱦᱟ ᱛᱮ ᱠᱩᱲᱤ ᱠᱚ ᱵᱚᱦᱚᱜ ᱠᱚ ᱥᱟᱡᱟᱣ ᱮᱫᱟ।","textLatin":"Sarjom baha te kuri ko bohog ko sajaw eda.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_8/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_complex_intermed_8/view?project=699495910038e39622c5","textBengali":"সারজম বাহা তে কুড়ি ক বহগ ক সাজাওয় এদা।","textHindi":"सारजम बाहा ते कुड़ि क बहग क साजाव एदा।","textOdia":"ସାରଜମ ବାହା ତେ କୁଡ଼ି କ ବହଗ କ ସାଜାୱ ଏଦା।","emotion":"Gratitude","storyArc":"Dreaming Big","growthValue":"Problem Solving","characterGoal":"Create something useful","imageDirection":"Olitun holding a vibrant wild flower, smelling its scent with a happy, relaxed expression. Show only the speaking character, never show both speakers in the same frame.","bodyLanguage":