INSERT OR REPLACE INTO lessons (id, category_id, title_ol_chiki, title_latin, lesson_type, order_index, raw_json) VALUES ('lesson_sentences_daily', 'cat_sentences_1778594024495', 'ᱫᱤᱱᱟᱹᱢ ᱣᱟᱠᱭ', 'Daily Sentences', NULL, 0, '{"id":"lesson_sentences_daily","categoryId":"cat_sentences_1778594024495","titleOlChiki":"ᱫᱤᱱᱟᱹᱢ ᱣᱟᱠᱭ","titleLatin":"Daily Sentences","level":"beginner","orderIndex":0,"isActive":true,"estimatedMinutes":5,"description":"","thumbnailUrl":null,"isPremium":false,"audioUrl":null,"blocks":[{"id":"text_0","order":0,"type":"text","markdown":"Ing do regenjing kana.","textOlChiki":"ᱤᱧ ᱫᱚ ᱨᱮᱸᱜᱮᱡᱤᱧ ᱠᱟᱱᱟ।","textLatin":"Ing do regenjing kana.","meta":{"textBengali":"ইঞ দ রেঁগেজিঞ কানা।","textHindi":"इञ द रेँगेजिञ काना।","textOdia":"ଇଞ ଦ ରେଁଗେଜିଞ କାନା।","pronunciation":"Ing do regenjing kana.","meaning":"I am hungry","meaning_en":"I am hungry","meaning_bn":"আমার খিদে পেয়েছে।","meaning_hi":"मुझे भूख लगी है।","meaning_or":"ମୋତେ ଭୋକ ଲାଗୁଛି।","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_daily_0/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_daily_0/view?project=699495910038e39622c5"},{"id":"text_1","order":1,"type":"text","markdown":"Daya kate jomag jom me.","textOlChiki":"ᱫᱟᱭᱟ ᱠᱟᱛᱮ ᱡᱚᱢᱟᱜ ᱡᱚᱢ ᱢᱮ।","textLatin":"Daya kate jomag jom me.","meta":{"textBengali":"দায়া কাতে জমাঃ জম মে।","textHindi":"दाया काते जमाग जम मे।","textOdia":"ଦାୟା କାତେ ଜମାଗ ଜମ ମେ।","pronunciation":"Daya kate jomag jom me.","meaning":"Please eat food","meaning_en":"Please eat food","meaning_bn":"দয়া করে খাবার খাও।","meaning_hi":"कृपया खाना खाओ।","meaning_or":"ଦୟାକରି ଖାଦ୍ୟ ଖାଅ।","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_daily_1/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_daily_1/view?project=699495910038e39622c5"},{"id":"text_2","order":2,"type":"text","markdown":"Daya kated dag nyui me.","textOlChiki":"ᱫᱟᱭᱟ ᱠᱟᱛᱮ ᱫᱟᱜ ᱧᱩᱭ ᱢᱮ।","textLatin":"Daya kated dag nyui me.","meta":{"textBengali":"দায়া কাতে দাঃ ঞুয় মে।","textHindi":"दाया काते दाग ञुय मे।","textOdia":"ଦାୟା କାତେ ଦାଗ ଞୁୟ ମେ।","pronunciation":"Daya kated dag nyui me.","meaning":"Please drink water.","meaning_en":"Please drink water.","meaning_bn":"দয়া করে জল খাও।","meaning_hi":"कृपया पानी पियो।","meaning_or":"ଦୟାକରି ପାଣି ପିଅ","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_daily_2/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_daily_2/view?project=699495910038e39622c5"},{"id":"text_3","order":3,"type":"text","markdown":"Inj donj parhag kana.","textOlChiki":"ᱤᱧ ᱫᱚᱧ ᱯᱟᱲᱦᱟᱜ ᱠᱟᱱᱟ।","textLatin":"Inj donj parhag kana.","meta":{"textBengali":"ইঞ দঞ পাড়হাঃ কানা।","textHindi":"इञ दञ पाड़हाग काना।","textOdia":"ଇଞ ଦଞ ପାଡ଼ହାଗ କାନା।","pronunciation":"Inj donj parhag kana.","meaning":"I am studying.","meaning_en":"I am studying.","meaning_bn":"আমি পড়াশোনা করছি।","meaning_hi":"अध्ययन कर रहा हूँ।","meaning_or":"ମୁଁ ଅଧ୍ୟୟନ କରୁଛି","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_daily_3/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_daily_3/view?project=699495910038e39622c5"},{"id":"text_4","order":4,"type":"text","markdown":"Biday johar. Ar hon Lang nyapama.","textOlChiki":"ᱵᱤᱫᱟᱹᱭ ᱡᱚᱦᱟᱨ। ᱟᱨ ᱦᱚᱸ ᱞᱟᱝ ᱧᱟᱯᱟᱢᱟ।","textLatin":"Biday johar. Ar hon Lang nyapama.","meta":{"textBengali":"বিদায় জহার। আর হঁ লাং ঞাপামা।","textHindi":"बिदाय जहार। आर हँ लाङ ञापामा।","textOdia":"ବିଦାୟ ଜହାର। ଆର ହଁ ଲାଙ ଞାପାମା।","pronunciation":"Biday johar. Ar hon Lang nyapama.","meaning":"Goodbye! See you again.","meaning_en":"Goodbye! See you again.","meaning_bn":"বিদায়! আবার দেখা হবে।","meaning_hi":"अलविदा! फिर मिलेंगे।","meaning_or":"ବିଦାୟ! ପୁଣି ଭେଟ ହେବା।","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_daily_4/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_sentences_daily_4/view?project=699495910038e39622c5"}],"order":1,"heroMediaUrl":null,"heroMediaType":null,"heroPosterUrl":null,"hero_media":null,"tracing":null,"isPreview":false}');
INSERT OR REPLACE INTO lessons (id, category_id, title_ol_chiki, title_latin, lesson_type, order_index, raw_json) VALUES ('lesson_greet_1', 'cat_phrases_1778594027629', 'ᱦᱚᱲ ᱥᱟᱶᱛᱟ ᱧᱟᱯᱟᱢ', 'Meeting People', NULL, 0, '{"id":"lesson_greet_1","categoryId":"cat_phrases_1778594027629","titleOlChiki":"ᱦᱚᱲ ᱥᱟᱶᱛᱟ ᱧᱟᱯᱟᱢ","titleLatin":"Meeting People","level":"beginner","orderIndex":0,"isActive":true,"estimatedMinutes":5,"description":"","thumbnailUrl":null,"isPremium":false,"audioUrl":null,"blocks":[{"id":"blk_text_0","order":0,"type":"text","markdown":"Amag njutum ched? – What is your name?","textOlChiki":"ᱟᱢᱟᱜ ᱧᱩᱛᱩᱢ ᱪᱮᱫ?","textLatin":"Amag njutum ched? – What is your name?","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_greet_1_0/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_greet_1_0/view?project=699495910038e39622c5","textBengali":"আমাঃ ঞুতুম চেদ?","textHindi":"आमाग ञुतुम चेद?","textOdia":"ଆମାଗ ଞୁତୁମ ଚେଦ?","pronunciation":"Amag njutum ched? – What is your name?","meaning":"What is your name?","meaning_en":"What is your name?","meaning_bn":"তোমার নাম কী?","meaning_hi":"तुम्हारा नाम क्या है?","meaning_or":"ତୁମର ନାମ କ’ଣ?"}},{"id":"blk_text_1","order":1,"type":"text","markdown":"Injag njutum do Phagun kana – My name is Fagun.","textOlChiki":"ᱤᱧᱟᱜ ᱧᱩᱛᱩᱢ ᱫᱚ ᱯᱷᱟᱹᱜᱩᱱ ᱠᱟᱱᱟ᱾","textLatin":"Injag njutum do Phagun kana – My name is Fagun.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_greet_1_1/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_greet_1_1/view?project=699495910038e39622c5","textBengali":"ইঞাগ ঞুতুম দ ফাগুন  কানা।","textHindi":"इञाग ञुतुम द फागुन  काना।","textOdia":"ଇଞାଗ ଞୁତୁମ ଦ ଫାଗୁନ  କାନା।","pronunciation":"Injag njutum do Phagun kana – My name is Fagun.","meaning":"My name is Fagun.","meaning_en":"My name is Fagun.","meaning_bn":"আমার নাম ফাগুন।","meaning_hi":"मेरा नाम है फागुन।","meaning_or":"ମୋର ନାମ ହେଉଛି ଫାଗୁନ।"}},{"id":"blk_text_2","order":2,"type":"text","markdown":"Am oka khonem hej kana? – Where are you from?","textOlChiki":"ᱟᱢ ᱚᱠᱟ ᱠᱷᱚᱱᱮᱢ ᱦᱮᱡ ᱠᱟᱱᱟ?","textLatin":"Am oka khonem hej kana? – Where are you from?","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_greet_1_2/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_greet_1_2/view?project=699495910038e39622c5","textBengali":"আম অকা খনেম হেজ কানা?","textHindi":"आम अका खनेम हेज काना?","textOdia":"ଆମ ଅକା ଖନେମ ହେଜ କାନା?","pronunciation":"Am oka khonem hej kana? – Where are you from?","meaning":"Where are you from?","meaning_en":"Where are you from?","meaning_bn":"আপনি কোথা থেকে এসেছেন?","meaning_hi":"आप कहाँ से हैं?","meaning_or":"ଆପଣ କେଉଁଠାରୁ ଆସିଛନ୍ତି?"}},{"id":"blk_text_3","order":3,"type":"text","markdown":"In do aatu khoninj hej kana – I am  from a village .","textOlChiki":"ᱤᱧ ᱫᱚ ᱟᱹᱛᱩ ᱠᱷᱚᱱᱤᱧ ᱦᱮᱡ ᱠᱟᱱᱟ᱾","textLatin":"In do aatu khoninj hej kana – I am  from a village .","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_greet_1_3/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_greet_1_3/view?project=699495910038e39622c5","textBengali":"ইঞ দ আতু খনিঞ হেজ কানা।","textHindi":"इञ द आतु खनिञ हेज काना।","textOdia":"ଇଞ ଦ ଆତୁ ଖନିଞ ହେଜ କାନା।","pronunciation":"In do aatu khoninj hej kana – I am  from a village .","meaning":"I am from a village","meaning_en":"I am from a village","meaning_bn":"আমি গ্রাম থেকে এসেছি।","meaning_hi":"मैं गाँव से आया हूं ।","meaning_or":"ମମୁଁ ଗାଁରୁ ଆସିଛି।"}},{"id":"blk_text_4","order":4,"type":"text","markdown":"Am saw njapam kate raskanj bujhau keda – Nice to meet you!","textOlChiki":"ᱟᱢ ᱥᱟᱶ ᱧᱟᱯᱟᱢ ᱠᱟᱛᱮ ᱨᱟᱹᱥᱠᱟᱹᱧ ᱵᱩᱡᱷᱟᱹᱣ ᱠᱮᱫᱟ","textLatin":"Am saw njapam kate raskanj bujhau keda – Nice to meet you!","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_greet_1_4/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_greet_1_4/view?project=699495910038e39622c5","textBengali":"আম সাওয় ঞাপাম কাতে রাসকাঞ বুঝাওয় কেদা।","textHindi":"आम साव ञापाम काते रासकाञ बुझाव केदा","textOdia":"ଆମ ସାୱ ଞାପାମ କାତେ ରାସକାଞ ବୁଝାୱ କେଦା","pronunciation":"Am saw njapam kate raskanj bujhau keda – Nice to meet you!","meaning":"Nice to meet you!","meaning_en":"Nice to meet you!","meaning_bn":"আপনার সাথে দেখা করে ভালো লাগলো!","meaning_hi":"आपसे मिलकर अच्छा लगा!","meaning_or":"ତୁମକୁ ଭେଟିବାକୁ ଭଲ ଲାଗିଲା!"}}],"order":1,"heroMediaUrl":null,"heroMediaType":null,"heroPosterUrl":null,"hero_media":null,"tracing":null,"isPreview":false}');
INSERT OR REPLACE INTO lessons (id, category_id, title_ol_chiki, title_latin, lesson_type, order_index, raw_json) VALUES ('lesson_alphabet_2', 'cat_alphabets_1778594017948', 'ᱠᱮᱪᱮᱫ ᱟᱲᱟᱝ II (ᱤ ᱟᱨ ᱩ ᱛᱷᱚᱠ)', 'Consonants: Group 2 (Palatal & Sibilant)', NULL, 0, '{"id":"lesson_alphabet_2","categoryId":"cat_alphabets_1778594017948","titleOlChiki":"ᱠᱮᱪᱮᱫ ᱟᱲᱟᱝ II (ᱤ ᱟᱨ ᱩ ᱛᱷᱚᱠ)","titleLatin":"Consonants: Group 2 (Palatal & Sibilant)","level":"beginner","orderIndex":0,"isActive":true,"estimatedMinutes":5,"description":"","thumbnailUrl":null,"isPremium":false,"audioUrl":null,"blocks":[{"id":"blk_0","order":0,"type":"text","markdown":"ᱥ (Is) – as in ᱥᱟᱹᱨᱤ (Sari: Truth / Real)","textOlChiki":"ᱥ - ᱥᱟᱹᱨᱤ","textLatin":"ᱥ (Is) – as in ᱥᱟᱹᱨᱤ (Sari: Truth / Real)","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/ltr_l_is/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/ltr_l_is/view?project=699495910038e39622c5","textBengali":"স - সারি (সত্য)","textHindi":"स - सारि (सत्य / सच)","textOdia":"ସ - ସାରି (ସତ୍ୟ)","pronunciation":"Is – Sari","meaning":"Consonant ᱥ (Is), as in ᱥᱟᱹᱨᱤ (Sari: Truth / Real)","meaning_en":"Consonant ᱥ (Is), as in ᱥᱟᱹᱨᱤ (Sari: Truth / Real)","meaning_bn":"ব্যঞ্জনবর্ণ ᱥ (ইস্), যেমন ᱥᱟᱹᱨᱤ (সারি: সত্য)","meaning_hi":"व्यंजन ᱥ (इस), जैसे ᱥᱟᱹᱨᱤ (सारि: सच)","meaning_or":"ବ୍ୟଞ୍ଜନବର୍ଣ୍ଣ ᱥ (ଇସ୍), ଯେପରି ସାରି (ସତ୍ୟ)"}},{"id":"blk_1","order":1,"type":"text","markdown":"ᱦ (Ih) – as in ᱦᱚᱲ (Hor: Person / Santal)","textOlChiki":"ᱦ - ᱦᱚᱲ","textLatin":"ᱦ (Ih) – as in ᱦᱚᱲ (Hor: Person / Santal)","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/ltr_l_ih/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/ltr_l_ih/view?project=699495910038e39622c5","textBengali":"হ - হড় (মানুষ)","textHindi":"ह - होड़ (इंसान / संताल)","textOdia":"ହ - ହୋଡ଼ (ମଣିଷ)","pronunciation":"Ih – Hor","meaning":"Consonant ᱦ (Ih), as in ᱦᱚᱲ (Hor: Person / Santal)","meaning_en":"Consonant ᱦ (Ih), as in ᱦᱚᱲ (Hor: Person / Santal)","meaning_bn":"ব্যঞ্জনবর্ণ ᱦ (ইহ্), যেমন ᱦᱚᱲ (হড়: মানুষ / সাঁওতাল)","meaning_hi":"व्यंजन ᱦ (इह), जैसे ᱦᱚᱲ (होड़: इंसान / संताल)","meaning_or":"ବ୍ୟଞ୍ଜନବର୍ଣ୍ଣ ᱦ (ଇହ୍), ଯେପରି ହୋଡ଼ (ମଣିଷ / ସାନ୍ତାଳ)"}},{"id":"blk_2","order":2,"type":"text","markdown":"ᱧ (Iny) – as in ᱧᱮᱞ (Nyel: To see / Look)","textOlChiki":"ᱧ - ᱧᱮᱞ","textLatin":"ᱧ (Iny) – as in ᱧᱮᱞ (Nyel: To see / Look)","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/ltr_l_iny/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/ltr_l_iny/view?project=699495910038e39622c5","textBengali":"ঞ - ঞেল (দেখা)","textHindi":"ञ - ञेल (देखना)","textOdia":"ଞ - ଞେଲ୍ (ଦେଖିବା)","pronunciation":"Iny – Nyel","meaning":"Consonant ᱧ (Iny), as in ᱧᱮᱞ (Nyel: To see / Look)","meaning_en":"Consonant ᱧ (Iny), as in ᱧᱮᱞ (Nyel: To see / Look)","meaning_bn":"ব্যঞ্জনবর্ণ ᱧ (ইঞ্), যেমন ᱧᱮᱞ (ঞেল: দেখা)","meaning_hi":"व्यंजन ᱧ (इञ), जैसे ᱧᱮᱞ (ञेल: देखना)","meaning_or":"ବ୍ୟଞ୍ଜନବର୍ଣ୍ଣ ᱧ (ଇଞ୍), ଯେପରି ଞେଲ୍ (ଦେଖିବା)"}},{"id":"blk_3","order":3,"type":"text","markdown":"ᱨ (Ir) – as in ᱨᱚᱲ (Ror: To speak / Speech)","textOlChiki":"ᱨ - ᱨᱚᱲ","textLatin":"ᱨ (Ir) – as in ᱨᱚᱲ (Ror: To speak / Speech)","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/ltr_l_ir/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/ltr_l_ir/view?project=699495910038e39622c5","textBengali":"র - রড় (কথা বলা)","textHindi":"र - रोड़ (बोलना)","textOdia":"ର - ରୋଡ଼ (କଥା କହିବା)","pronunciation":"Ir – Ror","meaning":"Consonant ᱨ (Ir), as in ᱨᱚᱲ (Ror: To speak / Speech)","meaning_en":"Consonant ᱨ (Ir), as in ᱨᱚᱲ (Ror: To speak / Speech)","meaning_bn":"ব্যঞ্জনবর্ণ ᱨ (ইর্), যেমন ᱨᱚᱲ (রড়: কথা বলা)","meaning_hi":"व्यंजन ᱨ (इर), जैसे ᱨᱚᱲ (रोड़: बोलना)","meaning_or":"ବ୍ୟଞ୍ଜନବର୍ଣ୍ଣ ᱨ (ଇର୍), ଯେପରି ରୋଡ଼ (କଥା କହିବା)"}},{"id":"blk_4","order":4