INSERT OR REPLACE INTO lessons (id, category_id, title_ol_chiki, title_latin, lesson_type, order_index, raw_json) VALUES ('lesson_alphabet_4', 'cat_alphabets_1778594017948', 'ᱡᱟᱯᱟᱜ ᱟᱲᱟᱝ ᱟᱨ ᱪᱤᱱᱦᱟᱹ', 'Modifiers & Signs (Japag Arang)', NULL, 0, '{"id":"lesson_alphabet_4","categoryId":"cat_alphabets_1778594017948","titleOlChiki":"ᱡᱟᱯᱟᱜ ᱟᱲᱟᱝ ᱟᱨ ᱪᱤᱱᱦᱟᱹ","titleLatin":"Modifiers & Signs (Japag Arang)","level":"beginner","orderIndex":0,"isActive":true,"estimatedMinutes":5,"description":"","thumbnailUrl":null,"isPremium":false,"audioUrl":null,"blocks":[{"id":"blk_0","order":0,"type":"text","markdown":"ᱹ (Gahla Tudag) – Baseline dot that deepens/opens vowel, as in ᱟᱹᱛᱩ (Atu: Village)","textOlChiki":"ᱹ - ᱜᱟᱹᱦᱞᱟᱹ ᱴᱩᱰᱟᱹᱜ","textLatin":"ᱹ (Gahla Tudag) – Baseline dot that deepens/opens vowel, as in ᱟᱹᱛᱩ (Atu: Village)","meta":{"textBengali":"গাহলা টুডাগ (নিচের বিন্দু) – স্বর গভীর করে, যেমন ᱟᱹᱛᱩ (গ্রাম)","textHindi":"गाहला टुडाग (निचला बिंदु) – स्वर को गहरा करता है, जैसे ᱟᱹᱛᱩ (गाँव)","textOdia":"ଗାହଲା ଟୁଡାଗ (ତଳ ବିନ୍ଦୁ) – ସ୍ୱରକୁ ଗଭୀର କରେ, ଯେପରି ᱟᱹᱛᱩ (ଗାଁ)","pronunciation":"Gahla Tudag – Atu","meaning":"Baseline dot modifying vowel into deep/open variant (e.g. ᱟ -> ᱟᱹ as in ᱟᱹᱛᱩ)","meaning_en":"Baseline dot modifying vowel into deep/open variant (e.g. ᱟ -> ᱟᱹ as in ᱟᱹᱛᱩ)","meaning_bn":"গাহলা টুডাগ (নিচের বিন্দু) – স্বর গভীর করে, যেমন ᱟᱹᱛᱩ (গ্রাম)","meaning_hi":"गाहला टुडाग – स्वर को गहरा बनाता है, जैसे ᱟᱹᱛᱩ (गाँव)","meaning_or":"ଗାହଲା ଟୁଡାଗ – ସ୍ୱରକୁ ଗଭୀର କରେ, ଯେପରି ᱟᱹᱛᱩ (ଗାଁ)","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_gahla_tudag/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_gahla_tudag/view?project=699495910038e39622c5"},{"id":"blk_1","order":1,"type":"text","markdown":"ᱸ (Mu Tudag) – Top dot for nasalization, as in ᱦᱮᱸ (Hẽ: Yes)","textOlChiki":"ᱸ - ᱢᱩ ᱴᱩᱰᱟᱹᱜ","textLatin":"ᱸ (Mu Tudag) – Top dot for nasalization, as in ᱦᱮᱸ (Hẽ: Yes)","meta":{"textBengali":"মু টুডাগ (নাসিক্য বিন্দু) – স্বর অনুনাসিক করে, যেমন ᱦᱮᱸ (হ্যাঁ)","textHindi":"मु टुडाग (नासिक बिंदु) – अनुनासिक ध्वनि बनाता है, जैसे ᱦᱮᱸ (हाँ)","textOdia":"ମୁ ଟୁଡାଗ (ନାସିକ୍ୟ ବିନ୍ଦୁ) – ନାସିକ୍ୟ ଧ୍ୱନି କରେ, ଯେପରି ᱦᱮᱸ (ହଁ)","pronunciation":"Mu Tudag – Hẽ","meaning":"Top dot adding nasalization to vowel (e.g. ᱦᱮᱸ: Yes)","meaning_en":"Top dot adding nasalization to vowel (e.g. ᱦᱮᱸ: Yes)","meaning_bn":"মু টুডাগ (উপরের বিন্দু) – অনুনাসিক ধ্বনি তৈরি করে, যেমন ᱦᱮᱸ (হ্যাঁ)","meaning_hi":"मु टुडाग – स्वर को अनुनासिक करता है, जैसे ᱦᱮᱸ (हाँ)","meaning_or":"ମୁ ଟୁଡାଗ – ନାସିକ୍ୟ ଧ୍ୱନି କରେ, ଯେପରି ᱦେᱸ (ହଁ)","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_mu_tudag/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_mu_tudag/view?project=699495910038e39622c5"},{"id":"blk_2","order":2,"type":"text","markdown":"ᱺ (Mu-Gahla Tudag) – Double dot for deep nasalized vowel, as in ᱥᱟᱺᱜᱤᱧ (Sanginj: Far)","textOlChiki":"ᱺ - ᱢᱩ-ᱜᱟᱹᱦᱞᱟᱹ ᱴᱩᱰᱟᱹᱜ","textLatin":"ᱺ (Mu-Gahla Tudag) – Double dot for deep nasalized vowel, as in ᱥᱟᱺᱜᱤᱧ (Sanginj: Far)","meta":{"textBengali":"মু-গাহলা টুডাগ – গভীর ও অনুনাসিক স্বর, যেমন ᱥᱟᱺᱜᱤᱧ (দূর)","textHindi":"मु-गाहला टुडाग – गहरा और अनुनासिक स्वर, जैसे ᱥᱟᱺᱜᱤᱧ (दूर)","textOdia":"ମୁ-ଗାହଲା ଟୁଡାଗ – ଗଭୀର ଓ ନାସିକ୍ୟ ସ୍ୱର, ଯେପରି ᱥᱟᱺଗିᱧ (ଦୂର)","pronunciation":"Mu-Gahla Tudag – Sanginj","meaning":"Colon-like double dot combining deepening and nasalization together","meaning_en":"Colon-like double dot combining deepening and nasalization together","meaning_bn":"মু-গাহলা টুডাগ – গভীর ও অনুনাসিক যুগল ধ্বনি, যেমন ᱥᱟᱺᱜᱤᱧ (দূর)","meaning_hi":"मु-गाहला टुडाग – गहरा और अनुनासिक का संयुक्त रूप, जैसे ᱥᱟᱺᱜᱤᱧ (दूर)","meaning_or":"ମୁ-ଗାହଲା ଟୁଡାଗ – ଗଭୀର ଓ ନାସିକ୍ୟର ସଂଯୁକ୍ତ ରୂପ","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_mu_gahla_tudag/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_mu_gahla_tudag/view?project=699495910038e39622c5"},{"id":"blk_3","order":3,"type":"text","markdown":"ᱽ (Ohod) – Deglottalizer mark releasing checked stops, as in ᱢᱮᱫᱽ (Med:eye)","textOlChiki":"ᱽ - ᱚᱦᱚᱫᱽ","textLatin":"ᱽ (Ohod) – Deglottalizer mark releasing checked stops, as in ᱢᱮᱫᱽ (Med:eye)","meta":{"textBengali":"অহদ","textHindi":"ओहद","textOdia":"ଅହଦ","pronunciation":"Ohod","meaning":"Deglottalizer releasing checked consonants ᱜ, ᱡ, ᱫ, ᱵ into continuous sounds","meaning_en":"Deglottalizer releasing checked consonants ᱜ, ᱡ, ᱫ, ᱵ into continuous sounds","meaning_bn":"অহদ – অবরুদ্ধ ব্যঞ্জনধ্বনিকে পূর্ণ কণ্ঠে প্রকাশ করে, যেমন ᱢᱮᱫᱽ ( চোখ)","meaning_hi":"ओहद – रुके हुए व्यंजन को मुक्त करता है, जैसे ᱢᱮᱫᱽ ( आँख )","meaning_or":"ଓହଦ୍ – ସ୍ୱର ପ୍ରବାହ ମୁକ୍ତ କରେ, ଯେପରି ᱢᱮᱫᱽ (ଆଖି)","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_ohod/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_ohod/view?project=699495910038e39622c5"},{"id":"blk_4","order":4,"type":"text","markdown":"ᱻ (rela) – Lengthens preceding vowel for melodic or poetic emphasis-ᱪᱮᱸᱻᱪᱮᱸ, ᱛᱟᱸᱻᱦᱟᱸᱻᱨᱮᱻᱛᱟ।","textOlChiki":"ᱻ - ᱨᱮᱞᱟ","textLatin":"ᱻ (rela) – Lengthens preceding vowel for melodic or poetic emphasis-ᱪᱮᱸᱻᱪᱮᱸ, ᱛᱟᱸᱻᱦᱟᱸᱻᱨᱮᱻᱛᱟ।","meta":{"textBengali":"ᱻ - রেলা","textHindi":"ᱻ - रेला","textOdia":"ᱻ- ରେଲା","pronunciation":"ᱻ (rela) – Lengthens preceding vowel for melodic or poetic emphasis-","meaning":"Vowel lengthener used for elongation in songs and chants -ᱪᱮᱸᱻᱪᱮᱸ, ᱛᱟᱸᱻᱦᱟᱸᱻᱨᱮᱻᱛᱟ।","meaning_en":"Vowel lengthener used for elongation in songs and chants -ᱪᱮᱸᱻᱪᱮᱸ, ᱛᱟᱸᱻᱦᱟᱸᱻᱨᱮᱻᱛᱟ।","meaning_bn":"রেলা– স্বরধ্বনি দীর্ঘায়িত করার চিহ্ন-ᱪᱮᱸᱻᱪᱮᱸ, ᱛᱟᱸᱻᱦᱟᱸᱻᱨᱮᱻᱛᱟ।","meaning_hi":"आहद – स्वर को दीर्घ करने का चिह्न-ᱪᱮᱸᱻᱪᱮᱸ, ᱛᱟᱸᱻᱦᱟᱸᱻᱨᱮᱻᱛᱟ।","meaning_or":"ଆହଦ୍ – ସ୍ୱରକୁ ଦୀର୍ଘ କରିବାର ଚିହ୍ନ-ᱪᱮᱸᱻᱪᱮᱸ, ᱛᱟᱸᱻᱦᱟᱸᱻᱨᱮᱻᱛᱟ।","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_rela/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_rela/view?project=699495910038e39622c5"},{"id":"blk_5","order":5,"type":"text","markdown":"᱾ (Mucaad) – Full stop punctuation mark, as in ᱤᱧ ᱚᱞᱚᱜ ᱠᱟᱱᱟᱹᱧ᱾ (I am reading.)","textOlChiki":"᱾ - ᱢᱩᱪᱟᱹᱫ","textLatin":"᱾ (Mucaad) – Full stop punctuation mark, as in ᱤᱧ ᱚᱞᱚᱜ ᱠᱟᱱᱟᱹᱧ᱾ (I am reading.)","meta":{"textBengali":"মুচাদ – পূর্ণচ্ছেদ (দাঁড়ি), যেমন ᱤᱧ ᱚᱞᱚᱜ ᱠᱟᱱᱟᱹᱧ᱾ (আমি পড়ছি।)","textHindi":"मुचाद – पूर्ण विराम (खड़ी पाई), जैसे ᱤᱧ ᱚᱞᱚᱜ ᱠᱟᱱᱟᱹᱧ᱾ (मैं पढ़ रहा हूँ।)","textOdia":"ମୁଚାଦ୍ – ପୂର୍ଣ୍ଣଚ୍ଛେଦ, ଯେପରି ᱤᱧ ᱚᱞᱚᱜ ᱠᱟᱱᱟᱹᱧ᱾ (ମୁଁ ପଢ଼ୁଛି।)","pronunciation":"Mucaad","meaning":"Sentence terminal punctuation mark (full stop)","meaning_en":"Sentence terminal punctuation mark (full stop)","meaning_bn":"মুচাদ – পূর্ণচ্ছেদ (দাঁড়ি / ফুলস্টপ)","meaning_hi":"मुचाद – पूर्ण विराम (खड़ी पाई)","meaning_or":"ମୁଚାଦ୍ – ପୂର୍ଣ୍ଣଚ୍ଛେଦ","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_mucaad/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_mucaad/view?project=699495910038e39622c5"},{"id":"blk_6","order":6,"type":"text","markdown":"(ᱼ)- ᱯᱷᱟᱨᱠᱟ – Separates words/syllables for clear pronunciation.","textOlChiki":"(ᱼ)- ᱯᱷᱟᱨᱠᱟ","textLatin":"Pharka – separates words/syllables for clear pronunciation.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_pharka/view?project=699495910038e39622c5","meta":{"textBengali":"ফারকা – শব্দ বা সিলেবল পৃথককারী চিহ্ন","textHindi":"फारका – शब्द या शब्दांश को अलग करने वाला चिह्न","textOdia":"ଫାରକା – ଶବ୍ଦ ବା ଶବ୍ଦାଂଶ ଅଲଗା କରିବା ଚିହ୍ନ","pronunciation":"Pharka","meaning":"Syllable / morpheme boundary separator sign","meaning_en":"Syllable / morpheme boundary separator sign","meaning_bn":"ফারকা – শব্দের সিলেবল আলাদা করার চিহ্ন","meaning_hi":"फारका – शब्दांश विभाजक चिह्न","meaning_or":"ଫାରକା – ଶବ୍ଦାଂଶ ବିଭାଜକ ଚିହ୍ନ","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_mod_pharka/view?project=699495910038e39622c5"}}],"order":4,"heroMediaUrl":null,"heroMediaType":null,"heroPosterUrl":null,"hero_media":null,"tracing":null,"isPreview":false}');
INSERT OR REPLACE INTO lessons (id, category_id, title_ol_chiki, title_latin, lesson_type, order_index, raw_json) VALUES ('lesson_grammar_verb_tenses', 'cat_sentences_1778594024495', 'ᱠᱟᱱᱣᱟ ᱚᱠᱛᱚ ᱪᱤᱱᱦᱟᱹ', 'Verb Tenses & Suffixes', NULL, 16, '{"id":"lesson_grammar_verb_tenses","categoryId":"cat_sentences_1778594024495","titleOlChiki":"ᱠᱟᱱᱣᱟ ᱚᱠᱛᱚ ᱪᱤᱱᱦᱟᱹ","titleLatin":"Verb Tenses & Suffixes","level":"beginner","orderIndex":16,"isActive":true,"estimatedMinutes":5,"description":"Master core Santali verb aspect suffixes: Present Continuous (-eda), Past Simple (-keda / -en), and Future (-a).","thumbnailUrl":null,"isPremium":false,"audioUrl":null,"blocks":[{"id":"b_gvt_1","order":0,"type":"text","markdown":"Parhaw ed-anj.","textOlChiki":"ᱯᱟᱲᱦᱟᱣ ᱮᱫ-ᱟᱹᱧ।","textLatin":"Parhaw ed-anj.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_0/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_0/view?project=699495910038e39622c5","textBengali":"পাড়হাওয় এদাঞ।","textHindi":"पाड़हाव एदाञ।","textOdia":"ପାଡ଼ହାୱ ଏଦାଞ।","grammarRule":"Present Continuous","meaning":"I am reading.","pronunciation":"Parhaw ed-anj.","meaning_en":"I am reading.","meaning_bn":"আমি পড়ছি","meaning_hi":"मैं पढ़ रहा हूँ","meaning_or":"ମୁଁ ପଢ଼ୁଛି"}},{"id":"b_gvt_2","order":1,"type":"text","markdown":"Jom ked-anj.","textOlChiki":"ᱡᱚᱢ ᱠᱮᱫ-ᱟᱹᱧ।","textLatin":"Jom ked-anj.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_1/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_1/view?project=699495910038e39622c5","textBengali":"জম কেদাঞ।","textHindi":"जम केदाञ।","textOdia":"ଜମ କେଦାଞ।","grammarRule":"Past Simple","meaning":"I ate.","pronunciation":"Jom ked-anj","meaning_en":"I ate.","meaning_bn":"আমি খেয়েছি।","meaning_hi":"मैंने खाया","meaning_or":"ମୁଁ ଖାଇଲି"}},{"id":"b_gvt_3","order":2,"type":"text","markdown":"Hijug-inj.","textOlChiki":"ᱦᱤᱡᱩᱜᱼᱤᱧ।","textLatin":"Hijug-inj.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_2/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_2/view?project=699495910038e39622c5","textBengali":"হিজুঃ ইঞ।","textHindi":"हिजुगइञ।","textOdia":"ହିଜୁଗଆଞ।","grammarRule":"Future Tense","meaning":"I will come.","pronunciation":"Hijug-inj.","meaning_en":"I will come.","meaning_bn":"আমি আসব।","meaning_hi":"मैं आऊँगा।","meaning_or":"ମୁଁ ଆସିବି।"}},{"id":"blk_text_3","order":3,"type":"text","markdown":"Inj donj jom keda.","textOlChiki":"ᱤᱧ ᱫᱚᱧ ᱡᱚᱢ ᱠᱮᱫᱟ।","textLatin":"Inj donj jom keda.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_3/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_3/view?project=699495910038e39622c5","textBengali":"ইঞ দঞ জম কেদা।","textHindi":"इञ दञ जम केदा।","textOdia":"ଇଞ ଦଞ ଜମ କେଦା।","pronunciation":"Inj donj jom keda.","meaning":"I ate.","meaning_en":"I ate.","meaning_bn":"আমি খেলাম।","meaning_hi":"मैंने खाया।","meaning_or":"ମୁଁ ଖାଇଲି"}},{"id":"blk_text_4","order":4,"type":"text","markdown":"Uni daka jomai.","textOlChiki":"ᱩᱱᱤ ᱫᱟᱠᱟ ᱡᱚᱢᱟᱭ।","textLatin":"Uni daka jomai.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_4/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_4/view?project=699495910038e39622c5","textBengali":"উনি দাকা জমায়।","textHindi":"उनि दाका जमाय।","textOdia":"ଉନି ଦାକା ଜମାୟ।","pronunciation":"Uni daka jomai.","meaning":"He/she will eat rice.","meaning_en":"He/she will eat rice.","meaning_bn":"সে ভাত খাবে।","meaning_hi":"वह चावल खाएगा / खाएगी।","meaning_or":"ସେ ଭାତ ଖାଇବ।"}},{"id":"blk_text_5","order":5,"type":"text","markdown":"Inj bazar chalag ing.","textOlChiki":"ᱤᱧ ᱵᱟᱡᱟᱨ ᱪᱟᱞᱟᱜ ᱤᱧ।","textLatin":"Inj bazar chalag ing.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_5/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_5/view?project=699495910038e39622c5","textBengali":"ইঞ বাজার চালাঃ ইঞ।","textHindi":"इञ बाजार चालाग इञ।","textOdia":"ଇଞ ବାଜାର ଚାଲାଗ ଇଞ।","pronunciation":"Inj bazar chalag ing.","meaning":"I will go to market.","meaning_en":"I will go to market.","meaning_bn":"আমি বাজার যাবো।","meaning_hi":"मैं बाजार जाऊँगी।","meaning_or":"ମୁଁ ବଜାର ଯିବି।"}},{"id":"blk_text_6","order":6,"type":"text","markdown":"Inj bazar tenj chalao lena.","textOlChiki":"ᱤᱧ ᱵᱟᱡᱟᱨ ᱛᱮᱧ ᱪᱟᱞᱟᱣ ᱞᱮᱱᱟ।","textLatin":"Inj bazar tenj chalao lena.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_6/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_6/view?project=699495910038e39622c5","textBengali":"ইঞ বাজার তেঞ চালাওয় লেনা।","textHindi":"इञ बाजार तेञ चालाव लेना।","textOdia":"ଇଞ ବାଜାର ତେଞ ଚାଲାୱ ଲେନା।","pronunciation":"Inj bazar tenj chalao lena.","meaning":"I went to the Market.","meaning_en":"I went to the Market.","meaning_bn":"আমি বাজারে গিয়েছিলাম।","meaning_hi":"मैं बाजार गया था / मैं बाजार गई थी।","meaning_or":"ମୁଁ ବଜାର ଯାଇଥିଲି।"}},{"id":"blk_text_7","order":7,"type":"text","markdown":"Ing bazar tenj chalag kana.","textOlChiki":"ᱤᱧ ᱵᱟᱡᱟᱨ ᱛᱮᱧ ᱪᱟᱞᱟᱜ ᱠᱟᱱᱟ।","textLatin":"Ing bazar tenj chalag kana.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_7/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_7/view?project=699495910038e39622c5","textBengali":"ইঞ বাজার তেঞ চালাঃ কানা।","textHindi":"इञ बाजार तेञ चालाग काना।","textOdia":"ଇଞ ବାଜାର ତେଞ ଚାଲାଗ କାନା।","pronunciation":"Ing bazar tenj chalag kana.","meaning":"I''m going to the Market.","meaning_en":"I''m going to the Market.","meaning_bn":"আমি বাজারে যাচ্ছি।","meaning_hi":"मैं बाजार जा रहा हूँ / जा रही हूँ।","meaning_or":"ମୁଁ ବଜାର ଯାଉଛି।"}},{"id":"blk_text_8","order":8,"type":"text","markdown":"Uni padhag kan tahed.","textOlChiki":"ᱩᱱᱤ ᱯᱟᱲᱦᱟᱜ ᱠᱟᱱ ᱛᱟᱦᱮᱸᱜ।","textLatin":"Uni padhag kan tahed.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_8/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_8/view?project=699495910038e39622c5","textBengali":"উনি পাড়হাঃ কান তাহেঁদ।","textHindi":"उनि पाड़हाग कान ताहेँग।","textOdia":"ଉନି ପାଡ଼ହାଗ କାନ ତାହେଁଗ।","pronunciation":"Uni padhag kan tahed.","meaning":"He was studying.","meaning_en":"He was studying.","meaning_bn":"সে পড়ছিল।","meaning_hi":"वह पढ़ रहा था।","meaning_or":"ସେ ପଢୁଥିଲା।"}},{"id":"blk_text_9","order":9,"type":"text","markdown":"Golu do japid edai.","textOlChiki":"ᱜᱳᱞᱩ ᱫᱚ ᱡᱟᱹᱯᱤᱫ ᱮᱫᱟᱭ।","textLatin":"Golu do japid edai.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_9/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_9/view?project=699495910038e39622c5","textBengali":"গোলু দ জাপিদ এদায়।","textHindi":"गोलु द जापिद एदाय।","textOdia":"ଗୋଲୁ ଦ ଜାପିଦ ଏଦାୟ।","pronunciation":"Golu do japid edai.","meaning":"Golu is sleeping.","meaning_en":"Golu is sleeping.","meaning_bn":"গোলু ঘুমোচ্ছে।","meaning_hi":"गोलू सो रहा है।","meaning_or":"ଗୋଲୁ ଶୋଉଛି।"}},{"id":"blk_text_10","order":10,"type":"text","markdown":"Chenre udog kanai.","textOlChiki":"ᱪᱮᱬᱮ ᱩᱰᱟᱹᱜ ᱠᱟᱱᱟᱭ।","textLatin":"Chenre udog kanai.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_10/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_verb_tenses_10/view?project=699495910038e39622c5","textBengali":"চেঁড়ে উডাঃ কানায়।","textHindi":"चेणे उडाग कानाय।","textOdia":"ଚେଣେ ଉଡାଗ କାନାୟ।","pronunciation":"Chenre udog kanai.","meaning":"The bird is flying.","meaning_en":"The bird is flying.","meaning_hi":"पक्षी उड़ रहा है।","meaning_or":"ପକ୍ଷୀ ଉଡୁଛି।"}}],"order":16,"heroMediaUrl":null,"heroMediaType":null,"heroPosterUrl":null,"hero_media":null,"tracing":null,"isPreview":false}');
INSERT OR REPLACE INTO lessons (id, category_id, title_ol_chiki, title_latin, lesson_type, order_index, raw_json) VALUES ('lesson_grammar_possessives', 'cat_sentences_1778594024495', 'ᱟᱯᱱᱟᱨ ᱥᱟᱹᱜᱟᱹᱭ ᱪᱤᱱᱦᱟᱹ', 'Possessives & Pronouns', NULL, 17, '{"id":"lesson_grammar_possessives","categoryId":"cat_sentences_1778594024495","titleOlChiki":"ᱟᱯᱱᱟᱨ ᱥᱟᱹᱜᱟᱹᱭ ᱪᱤᱱᱦᱟᱹ","titleLatin":"Possessives & Pronouns","level":"beginner","orderIndex":17,"isActive":true,"estimatedMinutes":5,"description":"Learn how to express ownership and relationships using genitive suffixes (-ag / -ak) with pronouns.","thumbnailUrl":null,"isPremium":false,"audioUrl":null,"blocks":[{"id":"b_gp_1","order":0,"type":"text","markdown":"Inyag","textOlChiki":"ᱤᱧᱟᱜ","textLatin":"Inyag","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_0/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_0/view?project=699495910038e39622c5","textBengali":"ইঞাঃ","textHindi":"इञाग","textOdia":"ଇଞାଗ","grammarRule":"Singular Possessives","meaning":"My / Mine","pronunciation":"Inyag","meaning_en":"My / Mine","meaning_bn":"আমার","meaning_hi":"मेरा","meaning_or":"ମୋର"}},{"id":"b_gp_2","order":1,"type":"text","markdown":"Aboyag","textOlChiki":"ᱟᱵᱚᱣᱟᱜ","textLatin":"Aboyag","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_1/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_1/view?project=699495910038e39622c5","textBengali":"আবওয়াগ","textHindi":"आबवाग","textOdia":"ଆବୱାଗ","grammarRule":"Plural Possessives","meaning":"Our (inclusive)","pronunciation":"Aboyag","meaning_en":"Our (inclusive)","meaning_bn":"আমাদের (সবার)","meaning_hi":"हमारा (सबका)","meaning_or":"ଆମର (ସମସ୍ତଙ୍କର)"}},{"id":"b_gp_3","order":2,"type":"text","markdown":"Uniyag","textOlChiki":"ᱩᱱᱤᱭᱟᱜ","textLatin":"Uniyag","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_2/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_2/view?project=699495910038e39622c5","textBengali":"উনিয়াঃ","textHindi":"उनियाग","textOdia":"ଉନିୟାଗ","grammarRule":"Third Person Possessives","meaning":"His / Her","pronunciation":"Uniyag","meaning_en":"His / Her","meaning_bn":"তার / ওঁর","meaning_hi":"उसका / उसकी","meaning_or":"ତାଙ୍କର"}},{"id":"blk_text_4","order":3,"type":"text","markdown":"unku-ag.","textOlChiki":"ᱩᱱᱠᱩᱟᱜ ।","textLatin":"unku-ag.","meta":{"textBengali":"উনকু আঃ ।","textHindi":"उनकुआग ।","textOdia":"ଉନକୁଆଗ ।","pronunciation":"unku-ag.","meaning":"Theirs","meaning_en":"Theirs","meaning_bn":"তাদের","meaning_hi":"उनका / उनके","meaning_or":"ସେମାନଙ୍କର।","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_3/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_3/view?project=699495910038e39622c5"},{"id":"blk_text_5","order":4,"type":"text","markdown":"amag","textOlChiki":"ᱟᱢᱟᱜ","textLatin":"amag","meta":{"textBengali":"আমাঃ","textHindi":"आमाग","textOdia":"ଆମାଗ","pronunciation":"amag","meaning":"Yours","meaning_en":"Yours","meaning_bn":"তোমার / আপনার","meaning_hi":"तुम्हारा / आपका","meaning_or":"ତୁମର / ଆପଣଙ୍କର","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_4/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_4/view?project=699495910038e39622c5"},{"id":"blk_text_6","order":5,"type":"text","markdown":"Aleyag","textOlChiki":"ᱟᱞᱮᱭᱟᱜ","textLatin":"Aleyag","meta":{"textBengali":"আলেয়াঃ","textHindi":"आलेयाग","textOdia":"ଆଲେୟାଗ","pronunciation":"Aleyag","meaning":"Ours (for more than two persons)","meaning_en":"Ours (for more than two persons)","meaning_bn":"আমাদের (যখন দুই জনের বেশি মানুষ কে বুঝায়)","meaning_hi":"हम सब का","meaning_or":"ଆମ ସମସ୍ତଙ୍କର","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_5/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_5/view?project=699495910038e39622c5"},{"id":"blk_text_7","order":6,"type":"text","markdown":"Apeyag","textOlChiki":"ᱟᱯᱮᱭᱟᱜ","textLatin":"Apeyag","meta":{"textBengali":"আপেয়াঃ","textHindi":"आपेयाग","textOdia":"ଆପେୟାଗ","pronunciation":"Apeyag","meaning":"Yours ( for more than two persons)","meaning_en":"Yours ( for more than two persons)","meaning_hi":"तुम सब का / आप सब का/तुम लोगों का/आप लोगों का","meaning_or":"ତୁମ ସମସ୍ତଙ୍କର / ଆପଣ ସମସ୍ତଙ୍କର","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_6/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_6/view?project=699495910038e39622c5"},{"id":"blk_text_8","order":7,"type":"text","markdown":"Alinjag","textOlChiki":"ᱟᱞᱤᱧᱟᱜ","textLatin":"Alinjag","meta":{"textBengali":"আলিঞাঃ","textHindi":"आलिञाग","textOdia":"ଆଲିଞାଗ","pronunciation":"Alinjag","meaning":"Ours (for two persons)","meaning_en":"Ours (for two persons)","meaning_bn":"আমাদের (দুই জনের জন্য)","meaning_hi":"हम दोनों का","meaning_or":"ଆମ ଦୁହିଁଙ୍କର","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_7/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_7/view?project=699495910038e39622c5"},{"id":"blk_text_9","order":8,"type":"text","markdown":"Abinag","textOlChiki":"ᱟᱵᱤᱱᱟᱜ","textLatin":"Abinag","meta":{"textBengali":"আবিনাঃ","textHindi":"आबिनाग","pronunciation":"Abinag","meaning":"Yours(for two persons)","meaning_en":"Yours(for two persons)","meaning_bn":"তোমাদের (দুই জনের জন্য)","meaning_hi":"तुम दोनों का/आप दोनों का","meaning_or":"ତୁମ ଦୁହିଁଙ୍କର","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_8/view?project=699495910038e39622c5"},"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_possessives_8/view?project=699495910038e39622c5"}],"order":17,"heroMediaUrl":null,"heroMediaType":null,"heroPosterUrl":null,"hero_media":null,"tracing":null,"isPreview":false}');
INSERT OR REPLACE INTO lessons (id, category_id, title_ol_chiki, title_latin, lesson_type, order_index, raw_json) VALUES ('lesson_grammar_plurals_numbers', 'cat_sentences_1778594024495', 'ᱥᱟᱸᱜᱮ ᱪᱤᱱᱦᱟᱹ ᱟᱨ ᱞᱮᱠᱷᱟ', 'Plurals & Number Agreements', NULL, 18, '{"id":"lesson_grammar_plurals_numbers","categoryId":"cat_sentences_1778594024495","titleOlChiki":"ᱥᱟᱸᱜᱮ ᱪᱤᱱᱦᱟᱹ ᱟᱨ ᱞᱮᱠᱷᱟ","titleLatin":"Plurals & Number Agreements","level":"beginner","orderIndex":18,"isActive":true,"estimatedMinutes":5,"description":"Understand plural (-ko), dual (-kin), and numeral classifier agreements in Santali.","thumbnailUrl":null,"isPremium":false,"audioUrl":null,"blocks":[{"id":"b_gpn_1","order":0,"type":"text","markdown":"Gatekin.","textOlChiki":"ᱜᱟᱛᱮᱠᱤᱱ।","textLatin":"Gatekin.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_plurals_numbers_0/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_plurals_numbers_0/view?project=699495910038e39622c5","textBengali":"গাতেকিন","textHindi":"गातेकिन।","textOdia":"ଗାତେକିନ।","grammarRule":"Dual Suffix","meaning":"Two friends.","pronunciation":"Gate-kin.","meaning_en":"Two friends.","meaning_bn":"দুই বন্ধু","meaning_hi":"दो दोस्त।","meaning_or":"ଦୁଇ ବନ୍ଧୁ।"}},{"id":"b_gpn_2","order":1,"type":"text","markdown":"Gidrako.","textOlChiki":"ᱜᱤᱫᱽᱨᱟᱹᱠᱚ।","textLatin":"Gidrako.","audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_plurals_numbers_1/view?project=699495910038e39622c5","meta":{"audioUrl":"https://sgp.cloud.appwrite.io/v1/storage/buckets/audio/files/snd_grammar_plurals_numbers_1/view?project=699495910038e39622c5","textBengali":"গিদরাক।","textHindi":"गिदराक।","textOdia":"ଗିଦରାକ।","grammarRule":"Plural Suffix","meaning":"Children.","pronunciation":"Gidra-ko.","meaning_en":"Children.","meaning_bn":"শিশুরা / বাচ্চারা","meaning_hi":"बच्चे","meaning_or":"ପିଲାମାନେ"}},{"id":"blk_text_3","order":2,"type":"text","mark